export const suiYunDetails: WuYunDetailTable = {"descript":"岁运统管全年的气候，反映全年的气候特征、物化特点等。关于岁运，《素问·六元正纪大论》言:“天气不足，地气随之；地气不足，天气从之。运居其中，而常先也”，即天气欲降，地气欲升，居中的运必首先为之升降，所以岁运又名中运。——《五运六气体质辨识及选方用药指导（体质篇）》","木运太过":{"item1":" ● 发生之纪：壬子、壬午、壬寅、壬申、壬辰、壬戌。","item2":" ● 上应：岁星","item3":" ● 五行：木↑，土↓，金↓","item4":" ● 气候：象春，全年温暖，多风，飓风时拔树毁屋。秋天金气来复时，天气骤然转凉，草木凋零。","item5":" ● 物候：生气疏布，万物繁荣，枝繁叶茂，果实不成。受影响的有麻稻，鸡犬，李桃，青黄白色，其味酸甘辛。","item6":" ● 人体：肝↑，脾↓，肺↓","item7":" ● 经络：经足厥阴少阳。","item8":" ● 疾病：病在巅顶，动风，头晕目眩，摇动、易怒，气逆，吐利。邪乃伤肝。"},"火运太过":{"item1":" ● 赫曦之纪：戊子、戊午、戊寅、戊申、戊辰、戊戌。","item2":" ● 上应：荧惑星","item3":" ● 五行：火↑，金↓，水↓","item4":" ● 气候：像夏，暑热过胜，火就燥，灼热气流，炎烈沸腾，常容易引起森林火灾。寒气来复，又容易出现暴雨、洪涝、霜雹。","item5":" ● 物候：长气旺，作物枝繁叶茂。受影响的有：麦豆，杏栗，其虫羽鳞，羊猪，其色赤白黑，其味苦辛咸。","item6":" ● 人体：心↑，肺↓，肾↓","item7":" ● 经络：手少阴太阳，手厥阴少阳。","item8":" ● 疾病：笑、热病、疮疡、血流、狂妄、目赤，邪伤心。咳嗽，便秘、皮肤病。"},"土运太过":{"item1":" ● 敦阜之纪：甲子、甲午、甲寅、甲申、甲辰、甲戌。","item2":" ● 上应：镇星","item3":" ● 五行：土↑，水↓，木↓","item4":" ● 气候：像长夏，湿热阴雨，雾重。","item5":" ● 物候：物化充成，果实累累","item6":" ● 人体：脾↑，肾↓","item7":" ● 经络：足太阴阳明经。","item8":" ● 疾病：气滞，腹满，四支不举。"},"金运太过":{"item1":" ● 坚成之纪：庚寅、庚申、庚子、庚午、庚辰、庚戌。","item2":" ● 上应：太白星","item3":" ● 五行：金↑，木↓，火↑↓","item4":" ● 气候：干燥，偏凉，秋早，收气繁布，化洽不终。","item5":" ● 物候：生长不旺，其变肃杀凋零。","item6":" ● 人体：肺↑，肝↓，心↑↓","item7":" ● 经络：手太阴肺经，手阳明大肠经","item8":" ● 疾病：喘喝，胸凭仰息。病势急切！"},"水运太过":{"item1":" ● 流衍之纪：丙寅、丙子、丙戌、丙申、丙午、丙辰。","item2":" ● 上应：水星","item3":" ● 五行：水↑，火↓，土↓","item4":" ● 气候：气温偏低，寒冷，多雨雪冰雹。","item5":" ● 物候：多洪涝，藏气太过，其象冬，长气衰，作物籽粒水分多不实，动物早冬眠。受影响的有谷、豆、栗、枣、鱼类、猪、牛，其色黑红黄，其味咸苦甘。","item6":" ● 人体：肾↑，心↓，脾↓","item7":" ● 疾病：其病胀，其经足少阴太阳，邪伤肾、心。","item8":" ● 经络：其经足少阴太阳。"},"木运不及":{"item1":" ● 委和之纪：丁卯、丁酉、丁丑、丁未、丁巳、丁亥。","item2":" ● 上应：岁星、灾三宫","item3":" ● 五行：木↓，金↑，土↑，火复气","item4":" ● 气化特征：春风无力百花残，生气不足，幼小遭殃。气候:春晚，春不暖，多雾，秋天提前，凉雨早降。","item5":" ● 物候：幼芽萎黄，仓干凋落，果实肉瘦，幼息不壮。受影响的有枣李，核壳，小米水稻，其味酸辛，其色白苍，狗鸡，有毛类和甲壳类动物。肃杀气胜，皆于三，则火气来复，其主飞虫、雉鸟耗，出现迅雷、霹雳。","item6":" ● 人体：肝↓，肺↑，脾↑","item7":" ● 疾病：肝系为主，摇动、震颤，大小筋拘挛或弛缓，容易发惊骇。肢体废用，浮肿，疮疡，邪伤肝也。","item8":""},"火运不及":{"item1":" ● 伏明之纪：癸丑、癸未、癸卯、癸酉、癸巳、癸亥","item2":" ● 上应：荧惑星，灾九宫","item3":" ● 五行：火↓，水↑，金↑","item4":" ● 气候：阳气不足，夏季不热，全年气温偏低。时有暴雨冰雪霜寒，凝惨溧冽。","item5":" ● 物候：长气不足，影响植物长壮，果实未大先老。阳气潜伏，蛰虫早藏。有翅膀的动物繁育受到影响。味苦咸，色黑丹。","item6":" ● 人体：心↓，肾↑，肺↑","item7":" ● 疾病：心阳被郁，易发痛症，多发心、脑、血管等血瘀梗阻性疾病。","item8":""},"土运不及":{"item1":" ● 卑监之纪：己巳、己卯、己丑、己亥、己酉、己未。","item2":" ● 上应：镇星，灾五宫","item3":" ● 五行：土↓，水↑，木↑","item4":" ● 气候：风寒并兴。","item5":" ● 物候：草木荣美，秀而不实，籽粒不成。","item6":" ● 人体：脾↓，肝↑，水↑","item7":" ● 疾病：邪伤脾，疡溃痈肿，濡滞，腹泻，留满否塞。","item8":""},"金运不及":{"item1":" ● 从革之纪：乙丑、乙未、乙卯、乙酉、乙巳、乙亥。","item2":" ● 上应：太白星，灾七宫","item3":" ● 五行：金↓，火↑，木↑","item4":" ● 气候：偏燥热，秋天迟到。","item5":" ● 物候：生长旺，收成欠。","item6":" ● 人体：肺↓，肝↑，火↑","item7":" ● 疾病：邪伤肺，咳喘，皮肤病、大便燥、泻。","item8":""},"水运不及":{"item1":" ● 涸流之纪：辛未、辛巳、辛丑、辛卯、辛亥、辛酉.","item2":" ● 上应：水星","item3":" ● 五行：水↓，火↑，土↑","item4":" ● 气候：少雨，干旱，雾霾，偏热。","item5":" ● 物候：反阳、水气蒸发，河水断流，泉水及水库等流动的水源减少，作物枯槁，蛰虫不藏；化气乃昌，受影响的作物有黍、小米、枣和杏子；受影响的动物是水从土化，如鱼、猪类，牛（裸虫）类；味道是咸从甘化，黑从黄化，其声羽（水）宫（土）","item6":" ● 人体：肾↓，心 ↑，脾↑","item7":" ●疾病：多见口干、皮肤干、尿少、血尿，阳痿,便秘。小几胆小易惊，耳病，头发枯燥稀少，牙病、骨病，个子矮小等。 ","item8":""}};

export const siTianDetails: LiuQiDetailTable = {"descript":"司天之气在上，位在南方，为客气的三之气，象征着在上的天之气，故亦称天气，主上半年的气候变化，统管上半年的初、二、三之气。如《素问·六元正纪大论》指出：“岁半之前，司天主之。”\n——《五运六气体质辨识及选方用药指（体质篇）》","厥阴风木":[{"title":"淫胜","content":"厥阴司天，风淫所胜，则太虚埃昏，云物以扰，寒生春气，流水不冰。民病胃脘当心而痛，上支两胁，鬲咽不通，饮食不下，舌本强，食则呕，冷泄腹胀，溏泻，瘕水闭，蛰虫不去，病本于脾。冲阳绝，死不治。","note":"厥阴司天，风气淫胜，则天空尘埃昏暗，云物扰动不宁，寒季行春令，流水不能结冰，蛰虫不去潜伏。人们多病胃脘，心部疼痛，上撑两胁，咽膈不通利，饮食不下，舌本强硬，食则呕吐，冷泻，腹胀，便溏泄，瘕，小便不通，病的根本在脾脏。如冲阳脉绝，多属不治的死症。"},{"title":"淫胜治则","content":"风淫所胜，平以辛凉，佐以苦甘，以甘缓之，以酸泻之。","note":"司天之气，风气淫胜，治以辛凉，佐以苦甘，以甘味缓其急，以酸味泻其邪。"},{"title":"复气","content":"厥阴之复，少腹坚满，里急暴痛。偃木飞沙，倮虫不荣。厥心痛，汗发呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。冲阳绝，死不治。","note":"厥阴风木之气变成复气的时候，形成的疾病表现为少腹坚满，里急暴痛的症状。如果复气严重则发生树木偃伏，沙土飞扬，倮虫不能发育等现象。复气严重时形成疾病表现为气厥心痛，出汗、呕吐，饮食不入，食入而又吐出，筋骨震颤，目眩，手足逆冷。严重的就会风邪入脾，成为食后吐出的食痹之症。往严重发展，等到冲阳脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"厥阴之复，治以酸寒，佐以甘辛，以酸泻之，以甘缓之。","note":"当厥阴风木之气变成复气形成疾病，治疗这类疾病应该以酸寒药物为主，以甘辛药物为辅，以酸味药物泻之，以甘味药物缓之。——《素问·至真要大论》"}],"少阳相火":[{"title":"淫胜","content":"少阳司天，火淫所胜，则温气流行，金政不平。民病头痛，发热恶寒而疟，热上皮肤痛，色变黄赤，传而为水，身面胕肿，腹满仰息，泄注赤白，疮疡咳唾血，烦心胸中热，甚则鼽衄，病本于肺。天府绝，死不治。","note":"少阳司天，火气淫胜，则温热之气流行，秋金之令不平。人们多病头痛，发热恶寒而发疟疾，热气在上，皮肤疼痛，色变黄赤，传于里则变为水病，身面浮肿，腹胀满，仰面喘息，泄泻暴注，赤白下痢，疮疡，咳嗽吐血，心烦，胸中热，甚至鼻流涕出血，病的根本在肺脏。如天腑脉绝，多属不治的死症。"},{"title":"淫胜治则","content":"火淫所胜，平以酸冷，佐以苦甘，以酸收之，以苦发之，以酸复之，热淫同。","note":"火气淫胜，治以咸冷，佐以苦甘，以酸味收敛阴气，以苦味药发泄火邪，以酸味药复其真气，热淫与火淫所胜相同。"},{"title":"复气","content":"少阳之复，大热将至，枯燥燔爇，介虫乃耗，惊瘛咳衄，心热烦躁，便数憎风，厥气上行，面如浮埃，目乃瘛，火气内发，上为口糜，呕逆，血溢血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴引水浆，色变黄赤，少气脉萎，化而为水，传为胕肿，甚则入肺，咳而血泄。尺泽绝，死不治。","note":"少阳相火之气变成复气的时候，大热的气候将会到来，草木被炎热的气候炙烤的干枯干燥，介虫因为不喜欢炎热的气候，因而介虫会被炎热的气候伤耗气血。形成的疾病表现为惊瘈咳衄，心热烦燥，小便频数，怕风。厥逆之气上行，面色就会像蒙上浮尘，眼睛也潏动引掣。火气在体内发作，就会上为口干，呕逆，或为血溢，下行则为便血。发为疟疾，就有恶寒鼓栗的现象。寒极反热，咽部干燥，渴欲饮水，脸色变为黄赤，少阳脉气萎弱。热寒之气在体内交争，转变成为浮肿，严重则邪气入肺，咳而有血。往严重发展，等到尺泽脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阳之复，治以咸冷，佐以苦辛，以咸软之，以酸收之，辛苦发之；发不远热，无犯温凉。少阴同法。","note":"当少阳相火之气变成复气形成疾病，治疗这类疾病应该以咸冷药物为主，以苦辛药物为辅，以咸味药物软之，以酸味药物收之，以辛苦味药物发之，发不要太过，不要远离了热气正常运行的规则，使其恢复正常即可停止，也不要犯了温凉二气的运行规则，不要用药太过或不及，以调节到气血正常运行为原则，少阴之复气所致的病，用发汗之药与此同法。 ——《素问·至真要大论》"}],"少阴君火":[{"title":"淫胜","content":"少阴司天，热淫所胜，怫热至，火行其政。民病胸巾烦热，嗌干，右胠满，皮肤痛，寒热咳喘，大雨且至，唾血血泄，鼽衄嚏呕，溺色变，甚则疮疡胕肿，肩背臂臑及缺盆中痛，心痛肺，腹大满，膨膨而喘咳，病本于肺，尺泽绝，死不治。","note":"少阴司天，热气淫胜，则天气郁热，君火行其政令，热极则大雨将至。人们多病胸中烦热，咽喉干燥，右胁上胀满，皮肤疼痛，寒热，咳喘，唾血，便血，衄血，鼻塞流涕，喷嚏，呕吐，小便为色，甚则疮疡，浮肿，肩、背、臂、臑以及缺盆等处疼痛，心痛，肺胀，腹胀满，胸部胀满，气喘咳嗽，病的根本在肺脏。如尺泽脉绝，多属不治的症。"},{"title":"淫胜治则","content":"热淫所胜，平以咸寒，佐以苦甘，以酸收之。","note":"热气淫胜，治以咸寒，佐以苦甘，以酸味收敛阴气。"},{"title":"复气","content":"少阴之复，懊热内作，烦燥鼽嚏，少腹绞痛，火见燔?，嗌燥分注时止，气动于左，上行于右，咳、皮肤痛、暴喑、心痛、郁冒不知人，乃洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气骨痿，隔肠不便，外为浮肿，哕噫。赤气后化，流水不冰，热气大行，介虫不复。病痱胗疮疡、痈疽痤痔，甚则入，肺，咳而鼻渊。天府绝，死不治。","note":"少阴君火之气变成复气的时候，形成的疾病表现为烦热从内部发作，烦躁，鼻流血，喷嚏，少腹绞痛，火现于外，身热如焚烧，咽嗌干燥，大小便时下时止，气动于左边而向上逆行于右侧，咳嗽，皮肤痛，突然失音，心痛，神志昏昏不省人事，继则洒浙恶寒，打寒战，妄言乱语，寒过去，又发烧，口渴而想喝水，少气，骨萎弱，肠道梗塞而大便不通，外现浮肿，呃逆嗳气。少阴君火之热气延后生化，致使流水在应该结冰的时令不能结冰，因此少阴君火热气大行，介虫因为喜欢清凉干燥的气候，属于自己的时令被火热的气候所占领，介虫因为不适应这种火热的气候，所以因为气候失常，介虫因此也不能恢复繁育昌盛。这时人们多患痱、胗、疮疡、痈疽、痤痔等外证，热邪过甚，就会入肺，发为咳嗽鼻渊。往严重发展，等到天府脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阴之复，治以咸寒，佐以苦辛，以甘泻之，以酸收之，辛苦发之，以咸软之。","note":"当少阴君火之气变成复气形成疾病，治疗这类疾病应该以咸寒药物为主，以苦辛药物为辅，以甘味药物泻之，以酸味药物收之，以辛苦药物发之，以咸味药物软之。 ——《素问·至真要大论》"}],"太阴湿土":[{"title":"淫胜","content":"太阴司天，湿淫所胜，则沉阴儿布，雨变枯槁。附肿骨痛阴痹，阴痹者按之不得，腰脊头项痛，时眩，大便难，阴气不用，饥不欲食，咳唾则有血，心如悬，病本于肾。太溪绝，死不治。","note":"太阴司天，湿气淫胜，则天气阴沉，乌云满布，雨多反使草木枯槁。人们多病浮肿，骨痛阴痹，阴痹之病按之不知痛处，腰脊头项疼痛，时时眩晕，大便困难，阳痿，饥饿而不欲进食，咳唾则有血，心悸如悬，病的根本在肾脏。如太溪脉绝，多属不治的死症。"},{"title":"淫胜治则","content":"湿淫所胜，平以苦热，佐以酸辛，以苦燥之，以淡泄之。湿上甚而热，治以苦温，佐以甘辛，以汗为故而止。","note":"湿气淫胜，治以苦热，佐以酸辛，以苦味药燥湿，以淡味泄湿邪如湿邪甚于上部而有热，治以苦味温性之药，佐以甘心，汗解法恢复其常态而止。"},{"title":"复气","content":"太阴之复，湿度乃举，体重中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声。大雨时行，鳞见于陆，头顶痛重，而掉瘈尤甚，呕而密默，唾吐清液，甚则入肾窍，泻无度。太溪绝，死不治。","note":"太阴湿土之气变成复气的时候，形成的疾病表现为湿气的病变就发生，身体沉重，胸满，饮食不消化，阴气上逆，胸中不爽快，水饮发于内，咳喘会夹杂着杂音。如果大雨时常下降，鳞虫类在平原陆地上出现。复气严重形成疾病表现为头顶痛重，在受到惊恐或震动的时候，更加厉害，呕吐，不愿动作，啐吐清水，往严重发展则湿邪入肾，泄泻没有节制。往严重发展，等到太溪脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阴之复，治以苦热，佐以酸辛，以苦泻之，燥之、泄之。","note":"当太阴湿土之气变成复气形成疾病，治疗这类疾病应该以苦热药物为主，以酸辛药物为辅，以苦味药物泻之，以燥味药物泄之。 ——《素问·至真要大论》"}],"阳明燥金":[{"title":"淫胜","content":"阳明司天，燥淫所胜，则木乃晚荣，草乃晚生，筋骨内变。民病左胠胁痛，寒清于中，感而疟，大凉革候，咳，腹中鸣，注泻鹜溏，名木敛，生菀于下，草焦上首，心胁暴痛，不可反侧，嗌干面尘腰痛，丈夫疝，妇人少腹痛，目眜眦，疡疮痤痈蛰虫来见，病本于肝。太冲绝，死不治。","note":"阳明司天，燥气淫胜，则树木繁荣推迟，草类生长较晚。筋骨发生变化，大凉之气使天气反常，树木生发之气被抑制而郁伏于下，草类的花叶均现焦枯，应该蛰伏的虫类反而出动。人们多病在肤胁疼痛，寒凉清肃之气感受之后则为疟疾，咳嗽，腹中鸣响，暴注泄泻，大便稀溏，心胁突然剧痛，不能转侧，咽喉干燥，面色如蒙尘，腰痛，男子癫疝，妇女少腹疼痛，眼目昏昧不明，眼角疼痛，疮疡痈痤，病的根本在肝脏。如太冲脉绝，多属不治的死症。"},{"title":"淫胜治则","content":"燥淫所胜，平以苦温，佐以酸辛，以苦下之。","note":"燥气淫胜，治以苦温，佐以酸辛，以苦味下其燥结。"},{"title":"复气","content":"阳明之复，清气大举，森木苍干，毛虫乃厉。病生胠胁，气归于左，善太息，甚则心痛，否满腹胀而泄，呕苦咳哕烦心，病在膈中，头痛，甚则入肝，惊骇筋挛。太冲绝，死不治。","note":"阳明燥金之气变成复气的时候，清凉之气就会大行，森林的树木开始变得苍老干枯，毛虫受到的伤害乃会非常厉害，因为毛虫喜欢春天温暖的环境，不能适应像秋天一样寒凉的气候。少阳相火变成复气形成疾病表现为疾病生于胠胁，其气偏于左侧不舒，爱叹息，严重则产生心痛，痞满，腹胀，泄泻，呕吐，咳嗽，呃逆，烦心。病在膈中，头痛，严重则邪气入肝，而发生惊惧、痉挛等症。往严重发展，等到太冲脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"阳明之复，治以辛温，佐以苦甘，以苦泄之，以苦下之，以酸补之。","note":"当阳明燥金之气变成复气形成疾病，治疗这类疾病应该以辛温药物为主，以苦甘药物为辅，以苦味药物泻之，以苦味药物下之，以酸味药物补之。 ——《素问·至真要大论》"}],"太阳寒水":[{"title":"淫胜","content":"太阳司天，寒淫所胜，则寒气反至，水且冰，血变于中，发为痈疡。民病厥心痛，呕血血泄鼽衄，善悲，时眩仆，运火炎烈，雨暴乃雹，胸腹满，手热肘挛掖肿，心澹澹大动，胸胁胃脘不安，面赤目黄，善噫，嗌干，甚则色炲，渴而欲饮，病本于心。神门绝，死不治。","note":"太阳司天，寒气淫胜，则寒气非时而至，水多结冰，如遇戊癸火运炎烈，则有暴雨冰雹。人们多病血脉变化于内，发生痈疡，厥逆心痛，呕血，便血，衄血，备塞流涕，善悲，时常眩晕仆倒，胸腹满，手热，肘臂挛急，腋部肿，心悸甚，胸胁胃脘不舒，面赤目黄，善嗳气，咽喉干燥，甚至面黑如炲，口渴欲饮，病的根本在心脏。如神门脉绝，多属不治的死症。"},{"title":"淫胜治则","content":"寒淫所胜，平以辛热，佐以甘苦，以咸泻之。","note":"寒气淫胜，治以辛热，佐以苦甘，以咸味药泄其寒邪。"},{"title":"复气","content":"太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆食减，腰脽反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睪，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。","note":"太阳寒水之气变成复气的时候，则寒厥之气上行，水气凝结为寒雨和冰，羽虫（带有翅膀的虫类）乃会死亡，因为羽虫喜欢比较炎热的气候，所以遇上寒冷的气候不能适应就会发生死亡。少阳相火变成复气形成疾病表现为心胃生寒气，胸中不舒适，心痛，痞满，头痛，多伤惧，经常眩晕仆倒，纳食减少，腰椎疼痛，屈伸极不方便。如果复气严重，则会地裂冰坚，阳光不显温暖，复气变严重形成疾病表现为少腹痛，牵引睾丸，连腰脊都痛，逆气上冲于心，唾出清水，呃逆嗳气，甚则邪气入心，发生善忘善悲的现象。往严重发展，等到神门脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阳之复，治以咸热，佐以甘辛，以苦坚之。","note":"当太阳寒水之气变成复气形成疾病，治疗这类疾病应该以咸热药物为主，以甘辛药物为辅，以苦味药物坚之。 ——《素问·至真要大论》"}]};

export const zaiQuanDetails: LiuQiDetailTable = {"descript":"在泉之气在下，位在北方，为客气的终之气，象征着在下的地之气，故亦称地气，主下半年的气候变化，统管下半年的四、五、终之气。如《素问·六元正纪大论》载:“岁半之后，地气主之。”\n——《五运六气体质辨识及选方用药指（体质篇）》","厥阴风木":[{"title":"淫胜","content":"岁厥阴在泉，风淫所胜，则地气不明，平野昧，草乃早秀。民病洒洒振寒，善伸数欠，心痛支满，两胁里急，饮食不下，膈咽不通，食则呕，腹胀善噫，得后与气，则快然如衰，身体皆重。","note":"厥阴风木之气在泉的年份，如果厥阴风木之气太过于强盛，风就会大发淫威，大风肆虐，则地气就会被风吹的昏暗不明，平野暗昧，草乃会早于正常的时令就会生长的秀丽。在这样病态的气候里人们多发的疾病是爱打寒颤，怕冷，爱伸懒腰，不适呻吟，不住地打哈欠，心痛并感觉胀满，两胁拘急不舒服，饮食不下没食欲，咽喉和胸膈不通畅，进食则呕吐，腹胀并且爱叹气，放屁或打嗝后会短暂感觉轻松，但是则很快就又回到衰弱的状态，感觉浑身沉重，全身乏力。"},{"title":"淫胜治则","content":"风淫于内，治以辛凉，佐以苦，以甘缓之，以辛散之。","note":"风气太过而侵淫体内的，主治用辛凉，辅佐用苦味，用甘味来缓和肝木，用辛味来散其风邪。"},{"title":"复气","content":"厥阴之复，少腹坚满，里急暴痛。偃木飞沙，?虫不荣。厥心痛，汗发呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。冲阳绝，死不治。","note":"厥阴风木之气变成复气的时候，形成的疾病表现为少腹坚满，里急暴痛的症状。如果复气严重则发生树木偃伏，沙土飞扬，倮虫不能发育等现象。复气严重时形成疾病表现为气厥心痛，出汗、呕吐，饮食不入，食入而又吐出，筋骨震颤，目眩，手足逆冷。严重的就会风邪入脾，成为食后吐出的食痹之症。往严重发展，等到冲阳脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"厥阴之复，治以酸寒，佐以甘辛，以酸泻之，以甘缓之。","note":"当厥阴风木之气变成复气形成疾病，治疗这类疾病应该以酸寒药物为主，以甘辛药物为辅，以酸味药物泻之，以甘味药物缓之。 ——《素问·至真要大论》"}],"少阳相火":[{"title":"淫胜","content":"岁少阳在泉，火淫所胜，则焰明郊野，寒热更至。民病注泄赤白，少腹痛，溺赤，甚则血便，少阴同候。","note":"少阳相火之气在泉的年份，如果少阳相火之气太过于强盛，火气就会大发淫威，火气肆虐，则像火焰一样灼热的空气使郊野变得明亮，寒热更替到来。在这样病态的气候里人们多发的疾病是泄泻如注，下痢赤白，少腹疼痛，小便赤红，严重的甚至大便下血，其余症状与少阴君火在泉之年的症状相同。"},{"title":"淫胜治则","content":"火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。","note":"火气太过而侵淫体内的，主治用咸冷,辅佐用苦辛,以酸味药收敛阴气，以苦味药发泄火邪。"},{"title":"复气","content":"少阳之复，大热将至，枯燥燔爇，介虫乃耗，惊瘛咳衄，心热烦躁，便数憎风，厥气上行，面如浮埃，目乃瘛，火气内发，上为口糜，呕逆，血溢血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴引水浆，色变黄赤，少气脉萎，化而为水，传为胕肿，甚则入肺，咳而血泄。尺泽绝，死不治。","note":"少阳相火之气变成复气的时候，大热的气候将会到来，草木被炎热的气候炙烤的干枯干燥，介虫因为不喜欢炎热的气候，因而介虫会被炎热的气候伤耗气血。形成的疾病表现为惊瘈咳衄，心热烦燥，小便频数，怕风。厥逆之气上行，面色就会像蒙上浮尘，眼睛也潏动引掣。火气在体内发作，就会上为口干，呕逆，或为血溢，下行则为便血。发为疟疾，就有恶寒鼓栗的现象。寒极反热，咽部干燥，渴欲饮水，脸色变为黄赤，少阳脉气萎弱。热寒之气在体内交争，转变成为浮肿，严重则邪气入肺，咳而有血。往严重发展，等到尺泽脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阳之复，治以咸冷，佐以苦辛，以咸软之，以酸收之，辛苦发之；发不远热，无犯温凉。少阴同法。","note":"当少阳相火之气变成复气形成疾病，治疗这类疾病应该以咸冷药物为主，以苦辛药物为辅，以咸味药物软之，以酸味药物收之，以辛苦味药物发之，发不要太过，不要远离了热气正常运行的规则，使其恢复正常即可停止，也不要犯了温凉二气的运行规则，不要用药太过或不及，以调节到气血正常运行为原则，少阴之复气所致的病，用发汗之药与此同法。 ——《素问·至真要大论》"}],"少阴君火":[{"title":"淫胜","content":"岁少阴在泉，热淫所胜，则焰浮川泽，阴处反明。民病腹中常呜，气上冲胸、喘、不能久立，寒热皮肤痛、目瞑齿痛、（出页）肿、恶寒发热如疟，少腹中痛、腹大、蛰虫不藏。","note":"少阴君火之气在泉的年份，如果少阴君火之气太过于强盛，热气就会大发淫威，热气肆虐，则热气就会像火焰漂浮在川泽上方一样，使人视物不清，在阴凉处反而视野清晰，看事物看的更清楚明白。在这样病态的气候里人们多发的疾病是腹中鸣响，逆气上冲胸部，气喘，不能久立，寒热，皮肤疼痛，视力模糊，齿疼，项肿，恶寒发热如疟疾，小腹疼痛，腹部胀大，因为气候炎热，所以蛰虫迟迟不蛰藏。"},{"title":"淫胜治则","content":"热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。","note":"热气太过而侵淫体内的，主治用咸寒，辅佐用甘苦，以酸味收敛阴气，用苦药来发泄热邪。"},{"title":"复气","content":"少阴之复，懊热内作，烦燥鼽嚏，少腹绞痛，火见燔?，嗌燥分注时止，气动于左，上行于右，咳、皮肤痛、暴喑、心痛、郁冒不知人，乃洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气骨痿，隔肠不便，外为浮肿，哕噫。赤气后化，流水不冰，热气大行，介虫不复。病痱胗疮疡、痈疽痤痔，甚则入，肺，咳而鼻渊。天府绝，死不治。","note":"少阴君火之气变成复气的时候，形成的疾病表现为烦热从内部发作，烦躁，鼻流血，喷嚏，少腹绞痛，火现于外，身热如焚烧，咽嗌干燥，大小便时下时止，气动于左边而向上逆行于右侧，咳嗽，皮肤痛，突然失音，心痛，神志昏昏不省人事，继则洒浙恶寒，打寒战，妄言乱语，寒过去，又发烧，口渴而想喝水，少气，骨萎弱，肠道梗塞而大便不通，外现浮肿，呃逆嗳气。少阴君火之热气延后生化，致使流水在应该结冰的时令不能结冰，因此少阴君火热气大行，介虫因为喜欢清凉干燥的气候，属于自己的时令被火热的气候所占领，介虫因为不适应这种火热的气候，所以因为气候失常，介虫因此也不能恢复繁育昌盛。这时人们多患痱、胗、疮疡、痈疽、痤痔等外证，热邪过甚，就会入肺，发为咳嗽鼻渊。往严重发展，等到天府脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阴之复，治以咸寒，佐以苦辛，以甘泻之，以酸收之，辛苦发之，以咸软之。","note":"当少阴君火之气变成复气形成疾病，治疗这类疾病应该以咸寒药物为主，以苦辛药物为辅，以甘味药物泻之，以酸味药物收之，以辛苦药物发之，以咸味药物软之。 ——《素问·至真要大论》"}],"太阴湿土":[{"title":"淫胜","content":"岁太阴在泉，草乃早荣，湿淫所胜，则埃昏岩谷，黄反见黑，至阴之交。民病饮积心痛，耳聋，浑浑焞焞，溢肿喉痹，阴病血见，少腹痛肿，不得小便，病冲头痛，目似脱，项似拔，腰似折，髀不可以回，腘如结，（月耑zhuan）如别。","note":"太阴湿土之气在泉的年份，如果太阴湿土之气太过于强盛，草乃会早于正常时令就会生长的繁荣，湿气就会大发淫威，湿气肆虐，则湿气混杂着尘埃就会使岩谷之地变得昏暗，于空气中漂浮的黄色尘埃中反而看见黑色的水气混杂在一起，与至阴之气交合在一起。在这样病态的气候里人们多发的疾病是饮邪积聚而心疼、耳聋、反应迟钝，咽喉肿胀、喉痹之类。阴病并有出血，少腹疼痛  、小便不利、气上冲头疼、眼如脱出、颈项部似拔折，或者说如折断，大腿不能转动，膝弯不灵活，小腿肚像要开裂。"},{"title":"淫胜治则","content":"湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。","note":"湿气太过而侵淫体内的，主治用苦热，辅佐用酸淡,用苦味药以燥湿,用淡味药以渗泄湿邪。"},{"title":"复气","content":"太阴之复，湿度乃举，体重中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声。大雨时行，鳞见于陆，头顶痛重，而掉瘈尤甚，呕而密默，唾吐清液，甚则入肾窍，泻无度。太溪绝，死不治。","note":"太阴湿土之气变成复气的时候，形成的疾病表现为湿气的病变就发生，身体沉重，胸满，饮食不消化，阴气上逆，胸中不爽快，水饮发于内，咳喘会夹杂着杂音。如果大雨时常下降，鳞虫类在平原陆地上出现。复气严重形成疾病表现为头顶痛重，在受到惊恐或震动的时候，更加厉害，呕吐，不愿动作，啐吐清水，往严重发展则湿邪入肾，泄泻没有节制。往严重发展，等到太溪脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阴之复，治以苦热，佐以酸辛，以苦泻之，燥之、泄之。","note":"当太阴湿土之气变成复气形成疾病，治疗这类疾病应该以苦热药物为主，以酸辛药物为辅，以苦味药物泻之，以燥味药物泄之。 ——《素问·至真要大论》"}],"阳明燥金":[{"title":"淫胜","content":"岁阳明在泉，燥淫所胜，则雾雾清瞑。民病喜呕，呕有苦，善太息，心胁痛，不能反侧，甚则嗌干，面尘，身无膏泽，足外反热。","note":"阳明燥金之气在泉的年份，如果阳明燥金之气太过于强盛，燥气就会大发淫威，燥气肆虐，则春秋季应该经常出现使人视物不清的雾露，潮湿的空气被燥气完全取代，空气中的水份被清凉干燥的肃杀气候所完全取代。在这样病态的气候里人们多发的疾病是时常作呕，呕吐苦水，频频叹息，胁部疼痛不能转侧，甚至咽喉干燥，面有尘灰之色，身体干枯无光泽，足外侧有发热现象。"},{"title":"淫胜治则","content":"燥淫于内，治以苦温，佐以甘辛，以苦下之。","note":"燥气太过而侵淫体内的，主治用苦温，辅助用甘辛，以苦味泄下。"},{"title":"复气","content":"阳明之复，清气大举，森木苍干，毛虫乃厉。病生胠胁，气归于左，善太息，甚则心痛，否满腹胀而泄，呕苦咳哕烦心，病在膈中，头痛，甚则入肝，惊骇筋挛。太冲绝，死不治。","note":"阳明燥金之气变成复气的时候，清凉之气就会大行，森林的树木开始变得苍老干枯，毛虫受到的伤害乃会非常厉害，因为毛虫喜欢春天温暖的环境，不能适应像秋天一样寒凉的气候。少阳相火变成复气形成疾病表现为疾病生于胠胁，其气偏于左侧不舒，爱叹息，严重则产生心痛，痞满，腹胀，泄泻，呕吐，咳嗽，呃逆，烦心。病在膈中，头痛，严重则邪气入肝，而发生惊惧、痉挛等症。往严重发展，等到太冲脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"阳明之复，治以辛温，佐以苦甘，以苦泄之，以苦下之，以酸补之。","note":"当阳明燥金之气变成复气形成疾病，治疗这类疾病应该以辛温药物为主，以苦甘药物为辅，以苦味药物泻之，以苦味药物下之，以酸味药物补之。——《素问·至真要大论》"}],"太阳寒水":[{"title":"淫胜","content":"岁太阳在泉，寒淫所胜，则凝肃惨栗。民病少腹控睪引腰脊，上冲心痛，血见嗌痛，颔肿。","note":"太阳寒水之气在泉的年份，如果太阳寒水之气太过于强盛，寒气就会大发淫威，寒气肆虐，则气候会异常寒冷，就呈现出凝肃惨厉的气象。在这样病态的气候里人们多发的疾病是少腹部疼痛引起睾丸疼痛，腰脊疼痛，上冲心腕作痛，出血，咽喉疼，颌下肿大。"},{"title":"淫胜治则","content":"寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。","note":"寒气太过而侵淫体内的，主治用甘热，辅助用苦辛，用成以水，脖味以温润，以苦味来巩固阳气。"},{"title":"复气","content":"太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆食减，腰脽反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睪，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。","note":"太阳寒水之气变成复气的时候，则寒厥之气上行，水气凝结为寒雨和冰，羽虫（带有翅膀的虫类）乃会死亡，因为羽虫喜欢比较炎热的气候，所以遇上寒冷的气候不能适应就会发生死亡。少阳相火变成复气形成疾病表现为心胃生寒气，胸中不舒适，心痛，痞满，头痛，多伤惧，经常眩晕仆倒，纳食减少，腰椎疼痛，屈伸极不方便。如果复气严重，则会地裂冰坚，阳光不显温暖，复气变严重形成疾病表现为少腹痛，牵引睾丸，连腰脊都痛，逆气上冲于心，唾出清水，呃逆嗳气，甚则邪气入心，发生善忘善悲的现象。往严重发展，等到神门脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阳之复，治以咸热，佐以甘辛，以苦坚之。","note":"当太阳寒水之气变成复气形成疾病，治疗这类疾病应该以咸热药物为主，以甘辛药物为辅，以苦味药物坚之。 \n——《素问·至真要大论》"}]};

export const zhuYunDetails: LiuQiDetailTable = {"descript":"主运主时指一年内主运五步运分主五时。主运主气候运行变化的正常规律，主运统运时，因太阳与地球间相对位置有规律的变化，导致一年之内出现春、夏、长夏、秋、冬五季的变化，我们用木、火、土、金、水分别表示这五个时段的五种气候特征，并名之为初运、二运、三运、四运、五运，合称五步运。\n——《五运六气体质辨识及选方用药指（体质篇）》","木运太过":[{"title":"三气之纪","content":"发生之纪，是谓启陈，土疏泄，苍气达，阳和布化，阴气乃随，生气淳化，万物以荣，其化生，其气美，其政散，其令条舒，其动掉眩巅疾，其德鸣靡启坼，其变振拉摧拔，其谷麻稻，其畜鸡犬，其果李桃，其色青黄白，其味酸甘辛，其象春，其经足厥阴少阳，其脏肝脾，其虫毛介，其物中坚外坚，其病怒，太角与上商同，上徵则其气逆，其病吐利，不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木雕零，邪乃伤肝。","note":"发生的年份，称为启陈。土气疏松虚薄，草木之青气发荣，阳气温和布化于四方，阴气随阳气而动，生气淳厚，化生万物，万物因之而欣欣向荣。其变化为生发，万物得其气则秀丽，其权力为散布，其权力的表现为舒展畅达，其在人体的变动是眩晕和巅顶部的疾病，其正常的性能是风和日暖，使万物奢靡华丽，推陈出新，若变动为狂风振怒，把树木摧折拔倒，在谷类是麻、稻，在畜类是鸡、犬，在果类是李、桃，在颜色是青、黄、白三色杂见，在五味是酸、甘、辛，其象征为春天，在人体的经络是足厥阴族少阳，其应于内脏为肝、脾，在虫类是毛虫介虫，在物体属内外坚硬的一类，若发病则为怒。这是木运太过，是为太角，木太过则相当于金气司天，故太角与上商同。若逢上徽，正当火气司天，木运太过亦能生火，火性上逆，木旺克土，故病发气逆、吐泻。木气太过失去了正常的性能，则金之收气来复，以致发生秋令劲切的景象，甚则有肃杀之气，气候清凉，草木凋零，若为人们的病变，则邪气伤在肝脏。\n——《素问·五常政大论》"},{"title":"胜","content":"木胜，岁木太过，风气流行，脾土受邪。民病飧泄，食减体重，烦冤、肠呜、腹支满，上应岁星。甚则忽忽善怒，眩冒巅疾，化气不政，生气独治，云物飞动，草木不宁，甚而摇落，反胁痛而吐甚，冲阳绝者，死不治，上应太白星。","note":"岁木之气太过，就会风气流行，脾土受到侵害，人们多患飨泄，饮食减少，肢体沉重，烦闷，肠鸣，肚腹胀满等上应天上的岁星。如果风气过度旺盛，在人体里就会产生骤然发怒、头眩、眼发黑花及头部疾病。这是土气不能行其政令，木气独胜的现象，因此，风气就更猖獗起来，使天上的云物飞扬，地上的草木动摇不定，甚至枝叶摇落，在人就会发生胁痛，呕吐不止。冲阳脉绝的，大多数会死亡，无法治疗，上应天上的金星。 \n——《素问·气交变大论》"},{"title":"复","content":"金复，太角与上商同，上徵则其气逆，其病吐利，不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木雕零，邪乃伤肝。","note":"太角与上商同。若逢上徽，正当火气司天，木运太过亦能生火，火性上逆，木旺克土，故病发气逆、吐泻。木气太过失去了正常的性能，则金之收气来复，以致发生秋令劲切的景象，甚则有肃杀之气，气候清凉，草木凋零，若为人们的病变，则邪气伤在肝脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"土郁，土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，胀呜而为数后，甚则心痛胁䐜[chēn] ，呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏，其乃发也。以其四气，云横天山，浮游生灭，怫之先兆。","note":"土郁发作时，山谷震动惊惧，隆隆雷声震动于气交之中，尘埃昏蒙，天地间昏黑。水湿化为白气，暴风骤雨降于高山深谷，击破山石，碎石飞于空中，洪水暴发漫溢川谷，大水退后，无数巨石耸立于田野，就象牧放的马匹。而后湿土之气敷布，时雨常降，于是自然万物开始生、长、化、成熟。所以人们易患腹胀满，肠鸣，大便次数增多，甚至心痛，胁肋撑胀，呕吐，霍乱，痰饮，水泻，浮肿，身重。云奔向南极，霞光壅遏早晨的太阳，山泽间尘埃昏蒙，这表明土郁将要暴发，发作的时间多在四时之气，浮云横于天山，或者飘浮，或者游动，或者产生，或者散失，这些都是郁结即将发作的先兆。 \n——《素问·六元正纪大论》"}],"火运太过":[{"title":"三气之纪","content":"赫曦之纪，是谓蕃茂，阴气内化，阳气外荣，炎暑施化，物得以昌，其化长，其气高，其政动，其令鸣显，其动炎灼妄扰，其德暄暑郁蒸，其变炎烈沸腾，其谷麦豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛咸，其象夏，其经手少阴太阳，手厥阴少阳，其脏心肺，其虫羽鳞，其物脉濡，其病笑疟疮疡血流狂妄目赤，上羽与正徵同，其收齐，其病痓，上徵而收气后也，暴烈其政，脏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。","note":"赫曦的年份，称为蕃茂。少阴之气从内而化，阳气发扬在外，炎暑的气候施行，万物得以昌盛。其生化之气为成长，火气的性质是上升，其权力是闪烁活动，其权力的表现为显露声色，其变动能使烧灼发热，并且因为过热而缭乱烦扰，其正常的性能是暑热郁郁蒸，其变化则为热度高张如烈火，在谷类是麦、豆，在畜类是羊、猪，在果类是杏、栗，在颜色是赤、白、黑，在五味是苦、辛、咸，其象征为夏天，在人体的经脉是手少阴、手太阳和手厥阴、手少阳，其应于内脏为心、肺，在虫类是羽虫鳞虫，在人体属脉络和津液，在人体的病变是因为心气实则笑，伤于暑则疟疾、疮疡、失血、发狂、目赤。火运太过，若逢太阳寒水司天，水能胜火，适得其平，故赫曦逢上羽，则和正徽相同。水运既平，金不受克，所以收令得以正常，因水气司天，水受火制，所以在人发病为厔。若火运太过又逢火气司天，二火相合，则金气受伤，故逢上徽则收气不能及时行令。由于火运行令，过于暴烈，水之藏气来复，以致时见阴凝惨淡的景象，甚至雨水霜雹，转为寒冷，若见病变，多是邪气伤于心脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"火胜，岁火太过，炎暑流行，金肺受邪。民病疟，少气、咳喘、血嗌、血泄、注下、溢燥、耳聋、中热、肩背热，上应荧惑星。甚则胸中痛，胁支满，胁痛、膺背肩胛间痛，两臂内痛，身热骨痛而为浸淫。收气不行，长气独明，雨水霜寒，上应辰星。上临少阴少阳，火燔焫，水泉涸，物焦槁，病反谵妄狂越，咳喘息呜，下甚，血溢泄不已，太渊绝者，死不治，上应荧惑星。","note":"岁火之气太过，就会暑热流行，肺金就要受到侵害，人们多患疟疾，呼吸少气，咳嗽气喘，吐血、衄血、便血，水泻如注，喉干、耳聋，胸中发热，肩背发热等病，上应天上的火星。如果火气过度旺盛，在人体就会有胸中疼痛，胁下胀满，胸膺部、背部、肩胛之间均感到疼痛，两臂内侧疼痛，身热，骨痛，因而发生浸淫疮。这是金气不行、火气独旺的现象。由于物极必反，水气乘之，因而出现雨水霜寒的变化，上应水星。如果遇到少阴、少阳司天，火热之气就会更加亢盛，好像火烧一样，以致水泉干涸，植物焦枯，人们的病，多见谵语狂乱，咳嗽气喘，呼吸有声，二便下血不止。肺脉绝的，大多数会死亡，无法治疗，上应火星。 \n——《素问·气交变大论》"},{"title":"复","content":"水复，上羽与正徵同，其收齐，其病痓，上徵而收气后也，暴烈其政，脏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。","note":"赫曦逢上羽，则和正徽相同。水运既平，金不受克，所以收令得以正常，因水气司天，水受火制，所以在人发病为厔。若火运太过又逢火气司天，二火相合，则金气受伤，故逢上徽则收气不能及时行令。由于火运行令，过于暴烈，水之藏气来复，以致时见阴凝惨淡的景象，甚至雨水霜雹，转为寒冷，若见病变，多是邪气伤于心脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"金郁，金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满引少腹，善暴痛，不可反侧，嗌干面尘，色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。","note":"金郁发作时，天气清洁，地气明亮，风清凉爽，气急切，清凉产生，草木上烟雾缭绕，燥气流行，雾气弥漫，肃杀之气降临，草木焦枯，秋声时鸣，所以人们患咳嗽，气逆，心胁胀满牵引腹中，经常出现突然疼痛，身体不能左右转动，咽喉干燥，尘土蒙面，面色败坏，山泽枯涸，地面上凝结出现象霜一样的白色盐卤，表明金郁将要暴发，其发多在五气当令之时，假若夜间降下白露，森林间发出凄惨的声音，就是金郁将发的先兆。 \n——《素问·六元正纪大论》"}],"土运太过":[{"title":"三气之纪","content":"敦阜之纪，是谓广化，厚德清静，顺长以盈，至阴内实，物化充成，烟埃朦郁，见于厚土，大雨时行，湿气乃用，燥政乃辟，其化圆，其气丰，其政静，其令周备，其动濡积并稸，其德柔润重淖，其变震惊飘骤崩溃，其谷稷麻，其畜牛犬，其果枣李，其色黅玄苍，其味甘咸酸，其象长夏，其经足太阴阳明，其脏脾肾，其虫倮毛，其物肌核，其病腹满四肢不举，大风迅至，邪伤脾也。","note":"敦阜的年份，称为广化。其德行浑厚而清静，使万物顺时生长乃至充盈，土的至阴之气充实，则万物能生化而成形，土运太过，故见土气蒸腾如烟，笼罩于山丘之上，大雨常下，湿气用事，燥气退避。其化圆满，其气丰盛，其权力则为静，其权力的表现是周密而祥备，其变动则湿气积聚，其性能柔润，使万物不断得到润泽，其变化则为暴雨骤至、雷霆震动、山崩堤溃，在谷类是稷、麻，在畜类是牛、犬，在果类是枣、李，在颜色是黄、黑、青，在五味是咸、酸，其象征为长夏，在人体的经脉是足太阴、足阳明，其应于内脏为脾、肾，在虫类是倮虫毛虫，在物体属于人体肌肉和植物果核的一类，在病变为腹中胀满，四肢沉重，举动不便，由于土运太过，木气来复，所以大风迅速而来，其所见的疾病，多由邪气伤于脾脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"土胜，岁土太过，雨湿流行，肾水受邪。民病腹痛，清厥、意不乐、体重烦冤、上应镇星。甚则肌肉痿，足痿不收行，善瘈，脚下痛、饮发中满、食减、四肢不举。变生得位，藏气伏化，气独治之，泉涌河衍，涸泽生鱼，风雨大至，土崩溃，鳞见于陆，病腹满溏泄，肠呜，反下甚，而太溪绝者，死不治。上应岁星。","note":"岁土之气太过，雨湿之气就会流行，肾水就要受到侵淫，人们多患腹痛，手足逆冷，情志抑郁，身体不轻快，烦闷等病，上应天上的土星。如果土气过度旺盛，在人体就会肌肉萎缩，两足痿弱不能行走，经常抽搐拘挛，脚跟痛，水邪蓄积于中，而生胀满，吃东西减少，以至四肢不能举动，水气无权、土气独旺的现象。因此泉水涌出，河水溢满，甚至干涸的池塘也生长了鱼类，甚至会发生急风暴雨，使堤岸崩溃，河水泛滥，陆地出现鱼类，在人就会患肚腹胀满、大便溏泻、肠鸣、泄泻不止等症。如果太溪脉绝止的，大多死亡，无法治疗。上应天上的木星。 \n——《素问·气交变大论》"},{"title":"复","content":"木复，其脏脾肾，其虫倮毛，其物肌核，其病腹满四肢不举，大风迅至，邪伤脾也。","note":"其应于内脏为脾、肾，在虫类是倮虫毛虫，在物体属于人体肌肉和植物果核的一类，在病变为腹中胀满，四肢沉重，举动不便，由于土运太过，木气来复，所以大风迅速而来，其所见的疾病，多由邪气伤于脾脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"水郁，水郁之发，阳气乃避，阴气暴举，大寒乃至，川泽严凝，寒氛结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰脽痛，大关节不利，屈伸不便，善厥阴，痞坚，腹满。阳光不治，空积沈阴，白埃昏瞑，而乃发也。其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。","note":"水郁发作时，阳气退避，阴气暴起，大寒降临，川泽之水凝结为坚冰，寒雾结为霜雪，甚至黄黑昏暗的水气流行于气交之中，成为霜杀之气，水出现应时变化。所以人们多患伤寒病证，心痛，腰及臀部疼痛，大的关节不灵活，屈伸不利，经常出现四肢逆冷，腹部痞满坚硬，阳气不能发挥作用，空中积满阴霾之气，白色尘埃昏暗，这就是水郁将发的现象，发作时其气常出现在君、相二火前后。太空高深色黑，其气如散麻一样混乱无绪，隐约可见，色黑而微黄，这就是水郁将发的先兆。 \n——《素问·六元正纪大论》"}],"金运太过":[{"title":"三气之纪","content":"坚成之纪，是谓收引，天气洁，地气明，阳气随，阴治化，燥行其政，物以司成，收气繁布，化洽不终，其化成，其气削，其政肃，其令锐切，其动暴折疡疰，其德雾露萧飋，其变肃杀雕零，其谷稻黍，其畜鸡马，其果桃杏，其色白青丹，其味辛酸苦，其象秋，其经手太阴阳明，其脏肺肝，其虫介羽，其物壳络，其病喘喝胸凭仰息，上徵与正商同，其生齐，其病咳，政暴变则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。","note":"坚成的年份，称为收引。天高气爽洁净，地气亦清静明朗，阳气跟随隐气的权力而生化，因为阳明燥金之气当权，于是万物都成熟，但金运太过，故秋收之气旺盛四布，以致长夏的化气未尽而顺从收气行令。其化是提早收成，其气是削伐，其权力过于严厉肃杀，它权力的表现是尖锐锋利而刚颈，其在人体之变动为强烈的折伤和疮疡、皮肤病，其正常的性能是散布雾露凉风，其变化则为肃杀凋零的景象，在谷类是稻、黍，在畜类是鸡、马，在果类是桃、杏，在颜色是白、青、丹，它化生的在五味是辛、酸、苦，其象征为秋天，在人体上相应的经脉是手太阴、手阳明，在内脏是肺与肝，化生的在虫类是介虫羽虫，生成物体是属于皮壳和筋络的一类，如果发生病变，大都为气喘有声而呼吸困难。若遇金运太过而逢火气司天的年份，因为火能克金适得其平，所以说上徽与正商相同。金气得到抑制，则木气不受克制，生气就能正常行令，发生的病变为咳嗽。金运太过的年份剧变暴虐，各种树木受到影响，不能发荣，使得草类柔软脆弱都会焦头，但继之火气来复，好象夏天的气候前来相救，故炎热的天气又流行，蔓草被烧灼而渐至枯槁，人们发生病变，多由邪气伤于肺脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"金胜，岁金太过，燥气流行，肝木受邪。民病两胁下，少腹痛，目赤痛、眦疡、耳无所闻。肃杀而甚，则体重烦冤，胸痛引背，两胁满且痛引少腹，上应太白星。甚则喘咳逆气，肩背痛；尻阴股膝髀腨（骨行）足皆病，上应荧惑星。收气峻，生气下，草木敛，苍干雕陨，病反暴痛，胠胁不可反侧，咳逆甚而血溢，太冲绝者，死不治。上应太白星。","note":"岁金之气太过，燥气就会流行，肝木就要受到侵害，人们多患两肋下面少腹疼痛，目赤痛，眼角痒，耳聋等病。燥金之气过于亢盛，就会身体沉重、烦闷、胸痛牵引到背部、两胁胀满，而痛势下连少腹，由于金气太过，上应天上的金星，金气过度旺盛，在人体就会有喘息咳嗽、逆气，肩背疼痛，下连股、膝、髀、腨、、足等处疼痛的病症，由于火气来复，上应火星，若是金气过于严峻，木气被它克制，草木就要呈收敛之象，以至绿叶干枯凋落，在人们的疾病中，多见急剧疼痛，胠胁痛得不能转动，咳嗽气逆，甚则吐血衄血。肝脉绝止的，大多死亡，无法治愈。上应天上的太白星。 \n——《素问·气交变大论》"},{"title":"复","content":"火复，上徵与正商同，其生齐，其病咳，政暴变则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。","note":"上徽与正商相同。金气得到抑制，则木气不受克制，生气就能正常行令，发生的病变为咳嗽。金运太过的年份剧变暴虐，各种树木受到影响，不能发荣，使得草类柔软脆弱都会焦头，但继之火气来复，好象夏天的气候前来相救，故炎热的天气又流行，蔓草被烧灼而渐至枯槁，人们发生病变，多由邪气伤于肺脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"木郁，木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，膈咽不通，食饮不下，甚则耳呜眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色黄黑郁若，横云不起雨，而乃发也。其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。","note":"木郁发作时，太空中尘埃昏暗，云物扰动，大风暴起，掀开屋顶，树木折断，草木变异。所以人们易患胃脘当心疼痛，向上支撑两胁，咽喉阻塞不通，饮食物吞咽不下。甚至出现耳鸣，头目晕眩转动，认不清人，常常突然出现僵仆倒地，太空中尘埃弥漫，天山混为一色而分辨不清。或者秽浊之气混为一团，颜色黄黑，象云横垣太空而不下雨。将要发时，天上云气变换无常，广阔的原野上草倒卧不起，柔弱的树叶翻转而背部向上，高山谷底松鸣虎啸，这些均是将要发作的先兆。 \n——《素问·六元正纪大论》"}],"水运太过":[{"title":"三气之纪","content":"流衍之纪，是谓封藏，寒司物化，天地严凝，藏政以布，长令不扬，其化凛，其气坚，其政谧，其令流注，其动漂泄沃涌，其德凝惨寒雰，其变冰雪霜雹，其谷豆稷，其畜彘牛，其果栗枣，其色黑丹黅，其味咸苦甘，其象冬，其经足少阴太阳，其脏肾心，其虫鳞倮，其物濡满，其病胀，上羽而长气不化也。政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。","note":"流衍的年份，称为封藏。寒气执掌万物的变化，天地间严寒阴凝，闭藏之气行使其权力，火的生长之气不得发扬。其化为凛冽，其气则坚凝，其权力为安静，它权力的表现是流动灌注，其活动则或为漂浮，或为下泻，或为灌溉，或为外溢，其性能是阴凝惨淡、寒冷雾气，其气候的变化为冰雪霜雹，在谷类是豆、稷，在畜类是猪、牛，在果类是栗、枣，显露的颜色是黑、朱红与黄，化生的五味是咸、苦、甘，其象征为冬天，在人体相应的经脉是足少阴、足太阳，其应于内脏为肾和心，化生的虫类是鳞虫倮虫，生成物体属充满汁液肌肉的一类，如果发生病变是胀。若逢水气司天，水运更太过，二水相合，火气更衰，故流衍逢上羽，火生长之气更不能发挥作用。如果水行太过，则土气来复，而化气发动，以致地气上升，大雨不时下降，人们发生的病变，由于邪气伤于肾脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"水胜，岁水太过，寒气流行，邪害心火。民病身热烦心，躁悸、阴厥、上下中寒、谵妄心痛、寒气早至，上应辰星。甚则腹大胫肿，喘咳寝汗出，憎风，大雨至，埃雾朦郁，上应镇星。上临太阳，雨冰雪霜不时降，湿气变物，病反腹满肠呜溏泄，食不化，渴而妄冒，神门绝者，死不治，上应荧惑辰星。","note":"岁水之气太过，就会寒气流行，心火从而受到侵害，人们多患身热、心烦、焦躁心跳，虚寒厥冷，全身发冷、谵语、心痛等病。在气候方面是寒气早至，上应水星水气过度旺盛，在人体就会有腹水、足胫浮肿、气喘咳嗽、盗汗、怕风等病症。由于水气盛，因而大雨下降，尘雾迷肿不清，土气来复，上应土星。如遇太阳寒水司天，则会冰雹霜雪不时下降，湿气太盛，致使物变其形。在人们的疾病中，多见肚腹胀满、肠鸣、溏泻、食物不化、渴而眩晕等症。心脉绝止的，大多数会死亡，无法治疗。上应水星却显得很亮。 \n——《素问·气交变大论》"},{"title":"复","content":"土复，政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。","note":"如果水行太过，则土气来复，而化气发动，以致地气上升，大雨不时下降，人们发生的病变，由于邪气伤于肾脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"火郁，火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背面首，四支䐜[chēn]愤，胪胀疡痱，呕逆瘈瘲，骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊?，善暴死。刻终大温，汗濡玄府，其乃发也。其气四。动复则静，阳极反阴，湿令乃化乃成，华发水凝，山川冰雪，焰阳午泽，怫之先兆也。","note":"火郁发作时，太空中昏朦不清，太阳光被遮盖而不明显，炎热流行，暴暑来临，山泽间如火燎烤，树木被蒸烤得流出汁液，大厦上升腾烟雾，地面上浮显出白色如霜的盐卤，聚积的水逐渐减少，蔓生的藤草枯萎焦黄，风热妄行。伤及心神，人们言语惑乱，湿的气化随后而生。所以人们患少气，疮疡痈肿，胁肋胸腹、背、头面、四肢胀满不适，生疮疡痱子，呕逆，筋脉抽搐，骨痛，关节抽动，泻下如注，温疟，腹中突然疼痛，血外流不止，精液减少，目赤，心热，甚至心中烦闷，昏晕等，容易引起突然死亡。一日百刻将尽时，气温升高，汗流满面。当发作时，多在四气之时。动到极点就转为静，阳极转阴，因而湿气乃化乃成。开花时节水反凝聚成冰，山川出现冰雪，中午时湖泽中出现烟雾，是火郁发作的先兆。 \n——《素问·六元正纪大论》"}],"木运不及":[{"title":"三气之纪","content":"委和之纪，是谓胜生，生气不政，化气乃扬，长气自平，收令乃早，凉雨时降，风云并兴，草木晚荣，苍干雕落，物秀而实，肤肉内充，其气敛，其用聚，其动緛戾拘缓，其发惊骇，其脏肝，其果枣李，其实核壳，其谷稷稻，其味酸辛，其色白苍，其畜犬鸡，其虫毛介，其主雾露凄沧，其声角商，其病摇动注恐，从金化也，少角与判商同，上角与正角同，上商与正商同，其病肢废痈肿疮疡，其甘虫，邪伤肝也，上宫与正宫同，萧飋肃杀则炎赫沸腾，眚于三，所谓复也，其主飞蠹蛆雉，乃为雷霆。","note":"委和的年份，称为胜生。生气不能很好的行使职权，化气于是发扬（土不畏木），长气自然平静（木不能生火），收令于是提早（金胜木），而凉雨不时下降，风云经常发起，草木不能及时繁荣，并且易于干枯凋落，万物早秀早熟，皮肉充实。其气收敛，其作用拘束，不得曲直伸展，在人体的变动是筋络拘挛无力，或者易于惊骇，其应于内脏为肝，在果类是枣、李，其所充实的是核和壳，在谷类是稷、稻，在五味是酸、辛，在颜色是白而苍，在畜类是犬和鸡，在虫类是毛虫和介虫，所主的气候是雾露寒冷之气，在声音是角、商，若发生病变则摇动和恐惧，这是由于木运不及而从金化的关系。所以少角等同判商。若逢厥阴风木司天，则不及的木运得司天之助，也可以成为平气，所以委和逢上角，则其气可与正角相同。若逢阳明燥金司天，则木运更衰，顺从金气用事，而成为金之平气，所以逢上商便和正商相同。在人体可发生四肢萎弱、痈肿、疮疡、生虫等病，这是由于雅气伤肝的关系。如正当太阴湿土司天，因土不畏，亦能形成土气用事，而成为土之平气，所以逢上宫则和正宫相同。故委年的年份，起初是一片肃杀的景象，但随之则为火热蒸腾，其灾害应于三（东方），这是由于金气克木，迫使火气前来报复。当火气来复，主多飞虫、蛆虫、蛆虫和雉木郁火复，发为雷霆。 \n——《素问·五常政大论》"},{"title":"胜","content":"金胜，岁木不及，燥乃大行，生气失应，草木晚荣，肃杀而甚，则刚木辟者，悉萎苍干，上应太白星。民病中清，胠胁痛，少腹痛，肠呜、溏泄。凉雨时至，上应太白星，其谷苍。上临阳明，生气失政，草木再荣，化气乃急，上应太白镇星，其主苍早。","note":"岁木之气不及，燥气然后流行，生气不能及时而来，草木就要晚荣。金气亢盛，劲硬的树木就会破折如劈，柔嫩的枝叶都会萎顿枯干，上应天上的金星。在人们则多患中气虚寒、胠胁部疼痛、少腹痛、肠鸣、溏泄。在气候方面，是凉雨时至。这一切均与天上的金星相应。在谷类，则不能成熟，呈现青苍色。如遇阳明司天，木气不能行其政令，土气兴起，草木再度繁茂，于是生化之气就显得峻急，而谷类也就不易结实了。因为燥、土二气俱盛，所以天的金星、土星俱明。 \n——《素问·气交变大论》"},{"title":"复","content":"火复，复则埃郁，大雨且至，黑气乃辱，病鹜溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身，上应镇星、辰星，玄谷不成。","note":"水气克火，则火的土气来复，于是土湿之气上蒸为云，大雨将至，水气下降，在人多见大便溏泻，腹满，饮食不下，肚中寒冷，肠鸣和泻下如注，腹痛，突然拘挛、痿、痹而足不能支持身体。上应土星水星，黑色之谷不能长熟。 \n——《素问·五常政大论》"},{"title":"郁发","content":"木郁，木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，膈咽不通，食饮不下，甚则耳呜眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色黄黑郁若，横云不起雨，而乃发也。其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。","note":"木郁发作时，太空中尘埃昏暗，云物扰动，大风暴起，掀开屋顶，树木折断，草木变异。所以人们易患胃脘当心疼痛，向上支撑两胁，咽喉阻塞不通，饮食物吞咽不下。甚至出现耳鸣，头目晕眩转动，认不清人，常常突然出现僵仆倒地，太空中尘埃弥漫，天山混为一色而分辨不清。或者秽浊之气混为一团，颜色黄黑，象云横垣太空而不下雨。将要发时，天上云气变换无常，广阔的原野上草倒卧不起，柔弱的树叶翻转而背部向上，高山谷底松鸣虎啸，这些均是将要发作的先兆。 \n——《素问·六元正纪大论》"}],"火运不及":[{"title":"三气之纪","content":"伏明之纪，是谓胜长，长气不宣，脏气反布，收气自政，化令乃衡，寒清数举，暑令乃薄，承化物生，生而不长，成实而稚，遇化已老，阳气屈伏，蛰虫早藏，其气郁，其用暴，其动彰伏变易，其发痛，其脏心，其果栗桃，其实络濡，其谷豆稻，其味苦咸，其色玄丹，其畜马彘，其虫羽鳞，其主冰雪霜寒，其声徵羽，其病昏惑悲忘，从水化也，少徵与少羽同，上商与正商同，邪伤心也，凝惨凛冽则暴雨霖霪，眚于九，其主骤注雷霆震惊，沉霒淫雨。","note":"伏明的年份，称为胜长。长气不得发扬，藏气反见布散，收气也擅自行使自行使职权，化气平定而不能发展，寒冷之气常现，暑热之气衰薄，万物虽承土的化气而生，但因火运不足，既生而不能成长，虽能结实，然而很小，及至生化的时候，已经衰老，阳气屈伏，蛰虫早藏。火气郁结，所以当其发作时，必然横暴，其变动每隐现多变，在人体病发为痛，其应于内脏为心，其在果类为栗和桃，其所充实的是络和汁，在谷类是豆和稻，在五味是苦和咸，在颜色是玄和丹，在畜类是马和猪，在虫类是羽虫鳞虫，在气候主冰雪霜寒，在声音是徽、羽，若发生病变则为精神昏乱，悲哀易忘，这是火运不及而从水化的关系。所以少徽和少羽相同。若逢阳明燥金司天，因金不畏火，形成金气用事，而成为金之平气，所以伏明逢上商则与正商相同。故所发之病，是由于邪气伤心，火运衰，所以有阴凝惨淡，寒风凛冽的现象，但随之而暴雨淋漓不止，其灾害于九（南方），这是土气来复，以致暴雨下注，雷霆震惊，乌云蔽日，阴雨连绵。 \n——《素问·五常政大论》"},{"title":"胜","content":"水胜，岁火不及，寒乃大行，长政不用，物荣而下。凝惨而甚，则阳气不化，乃折荣美，上应辰星。民病胸中痛、胁支满，两胁痛，膺背肩胛间及两臂内痛，郁冒蒙眛，心痛暴喑，胸复大，胁下与腰背相引而痛，甚则屈不能伸，髋髀如别，上应荧惑辰星，其谷丹。","note":"岁火之气不及，寒气就会大规模流行。夏天生长之气不能行其政令，植物就会由茂盛走向零落。寒凉之气过甚，阳气不能生化，因而万物的荣美也就被摧残了。相应天上的水星，在人们多患胸痛，胁部胀满，两胁疼痛，胸膺部、背部、肩胛之间以及两臂内侧都感疼痛，气都上冒，视物不清，心痛，突然失音，胸腹大，胁下与腰背互相牵引而痛，甚则病势发展到屈不能伸，髋骨与股部好像裂开一样。因为火受水气制约，所以上应天水星，五谷不成熟而其色红。 \n——《素问·气交变大论》"},{"title":"复","content":"土复，复则埃郁，大雨且至，黑气乃辱，病鹜溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身，上应镇星、辰星，玄谷不成。","note":"水气克火，则火的土气来复，于是土湿之气上蒸为云，大雨将至，水气下降，在人多见大便溏泻，腹满，饮食不下，肚中寒冷，肠鸣和泻下如注，腹痛，突然拘挛、痿、痹而足不能支持身体。上应土星水星，黑色之谷不能长熟。 \n——《素问·五常政大论》"},{"title":"郁发","content":"火郁，火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背面首，四支䐜[chēn]愤，胪胀疡痱，呕逆瘈瘲，骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊?，善暴死。刻终大温，汗濡玄府，其乃发也。其气四。动复则静，阳极反阴，湿令乃化乃成，华发水凝，山川冰雪，焰阳午泽，怫之先兆也。","note":"火郁发作时，太空中昏朦不清，太阳光被遮盖而不明显，炎热流行，暴暑来临，山泽间如火燎烤，树木被蒸烤得流出汁液，大厦上升腾烟雾，地面上浮显出白色如霜的盐卤，聚积的水逐渐减少，蔓生的藤草枯萎焦黄，风热妄行。伤及心神，人们言语惑乱，湿的气化随后而生。所以人们患少气，疮疡痈肿，胁肋胸腹、背、头面、四肢胀满不适，生疮疡痱子，呕逆，筋脉抽搐，骨痛，关节抽动，泻下如注，温疟，腹中突然疼痛，血外流不止，精液减少，目赤，心热，甚至心中烦闷，昏晕等，容易引起突然死亡。一日百刻将尽时，气温升高，汗流满面。当发作时，多在四气之时。动到极点就转为静，阳极转阴，因而湿气乃化乃成。开花时节水反凝聚成冰，山川出现冰雪，中午时湖泽中出现烟雾，是火郁发作的先兆。 \n——《素问·六元正纪大论》"}],"土运不及":[{"title":"三气之纪","content":"卑监之纪，是谓减化，化气不令，生政独彰，长气整，雨乃愆，收气平，风寒并兴，草木荣美，秀而不实，成而秕也，其气散，其用静定，其动疡涌分溃痈肿，其发濡滞，其脏脾，其果李栗，其实濡核，其谷豆麻，其味酸甘，其色苍黄，其畜牛犬，其虫倮毛，其主飘怒振发，其声宫角，其病留满痞塞，从木化也，少宫与少角同，上宫与正宫同，上角与正角同，其病飧泄，邪伤脾也，振拉飘扬则苍干散落，其眚四维，其主败折虎狼，清气乃用，生政乃辱。","note":"卑监的年份，称为减化。土的化气不得其令，而木的生气独旺，长气自能完整如常，雨水不能及时下降，收气平定，风寒并起，草木虽繁荣美丽，但秀而不能成实，所成的只是空壳或饱满的一类东西。其七散漫，其作用不足而过于静定，在人体的变动为病发疮疡，脓多、溃烂、痈肿，并发展为水气不行，其应于内脏为脾，在果类是李和栗，其所充实的是液汁和核，在谷类是豆和麻，在五味是酸、甘，在颜色是苍、黄，在畜类是牛和犬，在虫类是倮虫毛虫，因木胜风动，有振动摧折之势，在声音是宫、角，若发生病变则为胀满否塞不通，这是土运不及而从木化的关系。所以少宫和少角相同。若逢太阴湿土司天，虽土运不及，但得司天之助，也可成为平气，所以监逢上宫则和正宫相同。若逢厥阴风木司天，则土运更衰，顺从木气用事，而成为木知平气，所以逢上角则和正角相同。在发病来讲，消化不良的泄泻，是邪气伤脾的关系。土衰木胜，所以见风势振动，摧折飘扬的现象，随之而草木干枯凋落，其灾害应于中宫而通于四方。由于金气来复，所以有主败坏折伤，由于户；有如虎狼之势，清气发生作用，生气便被抑制而不能行使权力。 \n——《素问·五常政大论》"},{"title":"胜","content":"木胜，岁土不及，风乃大行，化气不令，草木茂荣。飘扬而甚，秀而不实，上应岁星。民病飧泄霍乱，体重腹痛，筋骨繇复，肌肉?酸，善怒，脏气举事，蛰虫早附，咸病寒中，上应岁星镇星，其谷黅。","note":"岁土之运不及，风气就大规模流行，而化气就不能行其政令。风木能生万物，所以草木茂盛，但因过分飘扬，虽然外秀却不能结实。上应木星，在人们多患飨泄、霍乱、身体重、腹痛、筋骨动摇强直、肌肉掣动发酸等症，并时常发怒。寒水之气乘机行动，虫类提前伏依在土里。人们一般都患中气虚寒。上应木星，土星，在谷类，其色黄而不能结实。 \n——《素问·气交变大论》"},{"title":"复","content":"金复，复则收政严峻，名木苍雕，胸胁暴痛，下引少腹，善大息，虫食甘黄，气客于脾， 谷乃减，民食少失味，苍谷乃损，上应太白、岁星。上临厥阴，流水不冰，蛰虫来见，脏气不用，白乃不复，上应岁星，民乃康。","note":"土受木气的克制，则其金气来复，于是秋气当令，呈现出肃杀严峻之气，因此大木凋谢，在人体就会有胸胁突然疼痛，牵引小腹，频频叹气等症。甘黄五谷都被虫食了。邪气客于脾土，黄色的谷类结实减少，人们吃得少，而且感到没有滋味。金气胜木，青色之谷受到损害，上应金星、木星。如遇厥阴司天，少阳在泉，则流水不能结冰，蛰伏的虫类又重新出现，寒水之气不能用事，金气也就不得再盛。上应木星，人们也就健康了。 \n——《素问·五常政大论》"},{"title":"郁发","content":"土郁，土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，胀呜而为数后，甚则心痛胁䐜[chēn] ，呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏，其乃发也。以其四气，云横天山，浮游生灭，怫之先兆。","note":"土郁发作时，山谷震动惊惧，隆隆雷声震动于气交之中，尘埃昏蒙，天地间昏黑。水湿化为白气，暴风骤雨降于高山深谷，击破山石，碎石飞于空中，洪水暴发漫溢川谷，大水退后，无数巨石耸立于田野，就象牧放的马匹。而后湿土之气敷布，时雨常降，于是自然万物开始生、长、化、成熟。所以人们易患腹胀满，肠鸣，大便次数增多，甚至心痛，胁肋撑胀，呕吐，霍乱，痰饮，水泻，浮肿，身重。云奔向南极，霞光壅遏早晨的太阳，山泽间尘埃昏蒙，这表明土郁将要暴发，发作的时间多在四时之气，浮云横于天山，或者飘浮，或者游动，或者产生，或者散失，这些都是郁结即将发作的先兆。 \n——《素问·六元正纪大论》"}],"金运不及":[{"title":"三气之纪","content":"从革之纪，是谓折收，收气乃后，生气乃扬，长化合德，火政乃宣，庶类以蕃，其气扬，其用躁切，其动铿禁瞀厥，其发咳喘，其脏肺，其果李杏，其实壳络，其谷麻麦，其味苦辛，其色白丹，其畜鸡羊，其虫介羽，其主明曜炎烁，其声商徵，其病嚏咳鼽衄，从火化也，少商与少徵同，上商与正商同，上角与正角同，邪伤肺也，炎光赫烈则冰雪霜雹，眚于七，其主鳞伏彘鼠，岁气早至，乃生大寒。","note":"从革的年份，称为折收，收气不能及时，生气得以发扬，长气和化气合而相得，火于是得以施行其权力，万物繁盛。其气发扬，其作用急噪，在人体的变动发病为咳嗽失音、烦闷气逆，发展为咳嗽气喘，其应于内脏为肺，在果类是李和杏，其所充实的是壳和络，在谷类是麻和麦，在五味是苦与辛，在颜色是白和朱红，在畜类是鸡和羊，在虫类是介虫羽虫。因为金虚火胜，主有发光灼热之势，在声音是商、徽，若发生病变则为喷嚏、咳嗽、鼻塞流滋、衄血，这是因金运不及而从火化的关系。所以少商和少徽相同。若逢阳明燥金司天，则金运虽不及，得司天之助，也能变为平气，所以从革逢上商就和正商相同。若逢厥阴风木司天，因金运不及，木不畏金，亦能形成木气用事而成为木知平气，所以逢上角便和正角相同。其病变是由于邪气伤于肺脏。因金衰火旺，所以火势炎热，但随之见冰雪霜雹，其灾害应于七（西方）。这是水气来复，故主如鳞虫伏藏，猪、鼠之阴沉，冬藏之气提早而至，于是发生大寒。 \n——《素问·五常政大论》"},{"title":"胜","content":"火胜，岁金不及，炎火乃行，生气乃用，长气专胜，庶物以茂，燥烁以行，上应荧惑星。民病肩背瞀重，鼽嚏、血便注下，收气乃后，上应太白星，其谷坚芒。","note":"岁金之气不及，火气就会流行，木气得行政令，生长之气专胜，万物因而繁茂。但火气旺盛了，气候就会干燥烁热。与此相应，天上火星光明。在人们多患肩背沉重，鼻流清涕，喷嚏，便血，泻下如注等病。金气被制，所以秋收之气后到。与此相应，天上金星失明，谷类不能成熟而呈现白色。 \n——《素问·气交变大论》"},{"title":"复","content":"水复，复则寒雨暴至，乃零冰雹霜雪杀物，阴厥且格，阳反上行，头脑户痛，延及囟顶发热，上应辰星，丹谷不成，民病口疮，甚则心痛。","note":"金气被制以后，它的水气来复，于是寒雨暴至，然后降落冰雹霜雪，杀害万物。在人就会为寒逆所扰，使阳气反而上行，以致头后部疼痛，连及脑顶，身体发热。上应水星，红色谷类不能成熟，人们多患口中生疮，甚至发生心痛等症。 \n——《素问·五常政大论》"},{"title":"郁发","content":"金郁，金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满引少腹，善暴痛，不可反侧，嗌干面尘，色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。","note":"金郁发作时，天气清洁，地气明亮，风清凉爽，气急切，清凉产生，草木上烟雾缭绕，燥气流行，雾气弥漫，肃杀之气降临，草木焦枯，秋声时鸣，所以人们患咳嗽，气逆，心胁胀满牵引腹中，经常出现突然疼痛，身体不能左右转动，咽喉干燥，尘土蒙面，面色败坏，山泽枯涸，地面上凝结出现象霜一样的白色盐卤，表明金郁将要暴发，其发多在五气当令之时，假若夜间降下白露，森林间发出凄惨的声音，就是金郁将发的先兆。 \n——《素问·六元正纪大论》"}],"水运不及":[{"title":"三气之纪","content":"涸流之纪，是谓反阳，藏令不举，化气乃昌，长气宣布，蛰虫不藏，土润水泉减，草木条茂，荣秀满盛，其气滞，其用渗泄，其动坚止，其发燥槁，其脏肾，其果枣杏，其实濡肉，其谷黍稷，其味甘咸，其色黅玄，其畜彘牛，其虫鳞倮，其主埃郁昏翳，其声羽宫，其病痿厥坚下，从土化也，少羽与少宫同，上宫与正宫同，其病癃閟，邪伤肾也，埃昏骤雨则振拉摧拔，眚于一，其主毛显狐狢，变化不藏。故乘危而行，不速而至，暴虐无德，灾反及之，微者复微，甚者复甚，气之常也。","note":"涸流的年份，称为反阳。藏气衰弱，不能行使其封藏的权力，化气因而昌盛，长气反见宣行而布达于四方，蛰虫应藏而不藏，土润泽而泉水减少，草木条达茂盛，万物繁荣秀丽而丰满。其气不得流畅，故其作用为暗中渗透泄，其变动为症结不行，发病为干躁枯槁，其应于内脏为肾，在果类是枣、杏，其所充实的是汁液和肉，在谷类是黍和稷，在五味是甘、咸，在颜色是黄、黑，在畜类是猪、牛，在虫类是鳞虫倮虫，水运衰，土气用事，故主有尘土昏郁的现象，在声音是羽、宫，在人体的病变为痿厥和下部的症结，这是水运不及而从土化的关系。所以少羽和少宫相同。若逢土气司天，则水运更衰，顺从土气用事，所以涸流逢上宫与正宫相同。其病见大小便不畅或闭塞不通，是邪气伤于肾脏。因水运不及，故尘埃昏蔽，或骤然下雨，但岁之反见大风振动，摧折倒拔，其灾害应于一（北方），这是木气来复，所以又见毛虫，善于变动而不主闭藏。 \n——《素问·五常政大论》"},{"title":"胜","content":"土胜，岁水不及，湿乃大行，长气反用，其化乃速，暑雨数至，上应镇星。民病腹满，身重濡泄，寒疡流水，腰股痛发，腘腨股膝不便，烦冤、足痿清厥，脚下痛，甚则胕肿，藏气不政，肾气不衡，上应辰星，其谷秬。上临太阴，则大寒数举，蛰虫早藏，地积坚冰，阳光不治，民病寒疾于下，甚则腹满浮肿，上应镇星，其主黅谷。","note":"岁水之气不及，湿气就大规模流行。水气不能制火，火气反行其令，其生化很快，暑雨屡次下降。与此相应，天上土星光明。在人们多患腹部胀满，身体重，湿泄，阴性疮疡，脓液稀薄，腰股发痛，腘、股、腨、膝部都不便利，烦闷，两脚萎弱，四肢清冷，脚下疼痛，甚则浮肿，这是冬藏之气不能行其政令，肾气失掉平衡的缘故。上应水星，黑色的谷类不能成熟。如遇太阴司天，寒水在泉，大的寒气常常侵袭，虫类很早就伏藏，地面上凝积厚冰，在天上的阳光不能发挥温暖作用，人们多患下部寒疾，严重的就腹满浮肿。上应土星，谷类黄色之稻成熟。 \n——《素问·气交变大论》"},{"title":"复","content":"木复，复则大风暴发，草偃木零，生长不鲜，面色时变，筋骨并辟，肉（目閏）瘛，目视（目巟）（目巟），物疏璺，肌肉胗发，气并鬲中，痛于心腹，黄气乃损，其谷不登，上应岁星。","note":"因为土气被水气制约，则其木气来复，就出现大风暴发，草类偃伏，木类凋零，因为风吹干裂，失去了生长的鲜泽。人的面色就也改变，筋骨拘急疼痛，肌肉跳动抽搐，两眼看物不清，有的东西看去像稍有裂纹，肌肉发出风疹。假如风气侵入胸膈里，就会产生心腹疼痛。这是木气太盛，土气受害，黄色的谷类不能成熟，而上应于木星。 \n——《素问·五常政大论》"},{"title":"郁发","content":"水郁，水郁之发，阳气乃避，阴气暴举，大寒乃至，川泽严凝，寒氛结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰脽痛，大关节不利，屈伸不便，善厥阴，痞坚，腹满。阳光不治，空积沈阴，白埃昏瞑，而乃发也。其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。","note":"水郁发作时，阳气退避，阴气暴起，大寒降临，川泽之水凝结为坚冰，寒雾结为霜雪，甚至黄黑昏暗的水气流行于气交之中，成为霜杀之气，水出现应时变化。所以人们多患伤寒病证，心痛，腰及臀部疼痛，大的关节不灵活，屈伸不利，经常出现四肢逆冷，腹部痞满坚硬，阳气不能发挥作用，空中积满阴霾之气，白色尘埃昏暗，这就是水郁将发的现象，发作时其气常出现在君、相二火前后。太空高深色黑，其气如散麻一样混乱无绪，隐约可见，色黑而微黄，这就是水郁将发的先兆。 \n——《素问·六元正纪大论》"}]};

export const keYunDetails: LiuQiDetailTable = {"descript":"客运与主运相对而言，主司十年或一年内气候运行变化的特殊规律。同主运一样，客运既可主岁又可主时，客运主岁即客运五运，分有太过和不及，每运统主两年气候变化，又叫客运统运。\n——《五运六气体质辨识及选方用药指（体质篇）》","木运太过":[{"title":"三气之纪","content":"发生之纪，是谓启陈，土疏泄，苍气达，阳和布化，阴气乃随，生气淳化，万物以荣，其化生，其气美，其政散，其令条舒，其动掉眩巅疾，其德鸣靡启坼，其变振拉摧拔，其谷麻稻，其畜鸡犬，其果李桃，其色青黄白，其味酸甘辛，其象春，其经足厥阴少阳，其脏肝脾，其虫毛介，其物中坚外坚，其病怒，太角与上商同，上徵则其气逆，其病吐利，不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木雕零，邪乃伤肝。","note":"发生的年份，称为启陈。土气疏松虚薄，草木之青气发荣，阳气温和布化于四方，阴气随阳气而动，生气淳厚，化生万物，万物因之而欣欣向荣。其变化为生发，万物得其气则秀丽，其权力为散布，其权力的表现为舒展畅达，其在人体的变动是眩晕和巅顶部的疾病，其正常的性能是风和日暖，使万物奢靡华丽，推陈出新，若变动为狂风振怒，把树木摧折拔倒，在谷类是麻、稻，在畜类是鸡、犬，在果类是李、桃，在颜色是青、黄、白三色杂见，在五味是酸、甘、辛，其象征为春天，在人体的经络是足厥阴族少阳，其应于内脏为肝、脾，在虫类是毛虫介虫，在物体属内外坚硬的一类，若发病则为怒。这是木运太过，是为太角，木太过则相当于金气司天，故太角与上商同。若逢上徽，正当火气司天，木运太过亦能生火，火性上逆，木旺克土，故病发气逆、吐泻。木气太过失去了正常的性能，则金之收气来复，以致发生秋令劲切的景象，甚则有肃杀之气，气候清凉，草木凋零，若为人们的病变，则邪气伤在肝脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"木胜，岁木太过，风气流行，脾土受邪。民病飧泄，食减体重，烦冤、肠呜、腹支满，上应岁星。甚则忽忽善怒，眩冒巅疾，化气不政，生气独治，云物飞动，草木不宁，甚而摇落，反胁痛而吐甚，冲阳绝者，死不治，上应太白星。","note":"岁木之气太过，就会风气流行，脾土受到侵害，人们多患飨泄，饮食减少，肢体沉重，烦闷，肠鸣，肚腹胀满等上应天上的岁星。如果风气过度旺盛，在人体里就会产生骤然发怒、头眩、眼发黑花及头部疾病。这是土气不能行其政令，木气独胜的现象，因此，风气就更猖獗起来，使天上的云物飞扬，地上的草木动摇不定，甚至枝叶摇落，在人就会发生胁痛，呕吐不止。冲阳脉绝的，大多数会死亡，无法治疗，上应天上的金星。 \n——《素问·气交变大论》"},{"title":"复","content":"金复，太角与上商同，上徵则其气逆，其病吐利，不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木雕零，邪乃伤肝。","note":"太角与上商同。若逢上徽，正当火气司天，木运太过亦能生火，火性上逆，木旺克土，故病发气逆、吐泻。木气太过失去了正常的性能，则金之收气来复，以致发生秋令劲切的景象，甚则有肃杀之气，气候清凉，草木凋零，若为人们的病变，则邪气伤在肝脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"土郁，土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，胀呜而为数后，甚则心痛胁䐜[chēn] ，呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏，其乃发也。以其四气，云横天山，浮游生灭，怫之先兆。","note":"土郁发作时，山谷震动惊惧，隆隆雷声震动于气交之中，尘埃昏蒙，天地间昏黑。水湿化为白气，暴风骤雨降于高山深谷，击破山石，碎石飞于空中，洪水暴发漫溢川谷，大水退后，无数巨石耸立于田野，就象牧放的马匹。而后湿土之气敷布，时雨常降，于是自然万物开始生、长、化、成熟。所以人们易患腹胀满，肠鸣，大便次数增多，甚至心痛，胁肋撑胀，呕吐，霍乱，痰饮，水泻，浮肿，身重。云奔向南极，霞光壅遏早晨的太阳，山泽间尘埃昏蒙，这表明土郁将要暴发，发作的时间多在四时之气，浮云横于天山，或者飘浮，或者游动，或者产生，或者散失，这些都是郁结即将发作的先兆。 \n——《素问·六元正纪大论》"}],"火运太过":[{"title":"三气之纪","content":"赫曦之纪，是谓蕃茂，阴气内化，阳气外荣，炎暑施化，物得以昌，其化长，其气高，其政动，其令鸣显，其动炎灼妄扰，其德暄暑郁蒸，其变炎烈沸腾，其谷麦豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛咸，其象夏，其经手少阴太阳，手厥阴少阳，其脏心肺，其虫羽鳞，其物脉濡，其病笑疟疮疡血流狂妄目赤，上羽与正徵同，其收齐，其病痓，上徵而收气后也，暴烈其政，脏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。","note":"赫曦的年份，称为蕃茂。少阴之气从内而化，阳气发扬在外，炎暑的气候施行，万物得以昌盛。其生化之气为成长，火气的性质是上升，其权力是闪烁活动，其权力的表现为显露声色，其变动能使烧灼发热，并且因为过热而缭乱烦扰，其正常的性能是暑热郁郁蒸，其变化则为热度高张如烈火，在谷类是麦、豆，在畜类是羊、猪，在果类是杏、栗，在颜色是赤、白、黑，在五味是苦、辛、咸，其象征为夏天，在人体的经脉是手少阴、手太阳和手厥阴、手少阳，其应于内脏为心、肺，在虫类是羽虫鳞虫，在人体属脉络和津液，在人体的病变是因为心气实则笑，伤于暑则疟疾、疮疡、失血、发狂、目赤。火运太过，若逢太阳寒水司天，水能胜火，适得其平，故赫曦逢上羽，则和正徽相同。水运既平，金不受克，所以收令得以正常，因水气司天，水受火制，所以在人发病为厔。若火运太过又逢火气司天，二火相合，则金气受伤，故逢上徽则收气不能及时行令。由于火运行令，过于暴烈，水之藏气来复，以致时见阴凝惨淡的景象，甚至雨水霜雹，转为寒冷，若见病变，多是邪气伤于心脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"火胜，岁火太过，炎暑流行，金肺受邪。民病疟，少气、咳喘、血嗌、血泄、注下、溢燥、耳聋、中热、肩背热，上应荧惑星。甚则胸中痛，胁支满，胁痛、膺背肩胛间痛，两臂内痛，身热骨痛而为浸淫。收气不行，长气独明，雨水霜寒，上应辰星。上临少阴少阳，火燔焫，水泉涸，物焦槁，病反谵妄狂越，咳喘息呜，下甚，血溢泄不已，太渊绝者，死不治，上应荧惑星。","note":"岁火之气太过，就会暑热流行，肺金就要受到侵害，人们多患疟疾，呼吸少气，咳嗽气喘，吐血、衄血、便血，水泻如注，喉干、耳聋，胸中发热，肩背发热等病，上应天上的火星。如果火气过度旺盛，在人体就会有胸中疼痛，胁下胀满，胸膺部、背部、肩胛之间均感到疼痛，两臂内侧疼痛，身热，骨痛，因而发生浸淫疮。这是金气不行、火气独旺的现象。由于物极必反，水气乘之，因而出现雨水霜寒的变化，上应水星。如果遇到少阴、少阳司天，火热之气就会更加亢盛，好像火烧一样，以致水泉干涸，植物焦枯，人们的病，多见谵语狂乱，咳嗽气喘，呼吸有声，二便下血不止。肺脉绝的，大多数会死亡，无法治疗，上应火星。 \n——《素问·气交变大论》"},{"title":"复","content":"水复，上羽与正徵同，其收齐，其病痓，上徵而收气后也，暴烈其政，脏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。","note":"赫曦逢上羽，则和正徽相同。水运既平，金不受克，所以收令得以正常，因水气司天，水受火制，所以在人发病为厔。若火运太过又逢火气司天，二火相合，则金气受伤，故逢上徽则收气不能及时行令。由于火运行令，过于暴烈，水之藏气来复，以致时见阴凝惨淡的景象，甚至雨水霜雹，转为寒冷，若见病变，多是邪气伤于心脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"金郁，金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满引少腹，善暴痛，不可反侧，嗌干面尘，色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。","note":"金郁发作时，天气清洁，地气明亮，风清凉爽，气急切，清凉产生，草木上烟雾缭绕，燥气流行，雾气弥漫，肃杀之气降临，草木焦枯，秋声时鸣，所以人们患咳嗽，气逆，心胁胀满牵引腹中，经常出现突然疼痛，身体不能左右转动，咽喉干燥，尘土蒙面，面色败坏，山泽枯涸，地面上凝结出现象霜一样的白色盐卤，表明金郁将要暴发，其发多在五气当令之时，假若夜间降下白露，森林间发出凄惨的声音，就是金郁将发的先兆。 \n——《素问·六元正纪大论》"}],"土运太过":[{"title":"三气之纪","content":"敦阜之纪，是谓广化，厚德清静，顺长以盈，至阴内实，物化充成，烟埃朦郁，见于厚土，大雨时行，湿气乃用，燥政乃辟，其化圆，其气丰，其政静，其令周备，其动濡积并稸，其德柔润重淖，其变震惊飘骤崩溃，其谷稷麻，其畜牛犬，其果枣李，其色黅玄苍，其味甘咸酸，其象长夏，其经足太阴阳明，其脏脾肾，其虫倮毛，其物肌核，其病腹满四肢不举，大风迅至，邪伤脾也。","note":"敦阜的年份，称为广化。其德行浑厚而清静，使万物顺时生长乃至充盈，土的至阴之气充实，则万物能生化而成形，土运太过，故见土气蒸腾如烟，笼罩于山丘之上，大雨常下，湿气用事，燥气退避。其化圆满，其气丰盛，其权力则为静，其权力的表现是周密而祥备，其变动则湿气积聚，其性能柔润，使万物不断得到润泽，其变化则为暴雨骤至、雷霆震动、山崩堤溃，在谷类是稷、麻，在畜类是牛、犬，在果类是枣、李，在颜色是黄、黑、青，在五味是咸、酸，其象征为长夏，在人体的经脉是足太阴、足阳明，其应于内脏为脾、肾，在虫类是倮虫毛虫，在物体属于人体肌肉和植物果核的一类，在病变为腹中胀满，四肢沉重，举动不便，由于土运太过，木气来复，所以大风迅速而来，其所见的疾病，多由邪气伤于脾脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"土胜，岁土太过，雨湿流行，肾水受邪。民病腹痛，清厥、意不乐、体重烦冤、上应镇星。甚则肌肉痿，足痿不收行，善瘈，脚下痛、饮发中满、食减、四肢不举。变生得位，藏气伏化，气独治之，泉涌河衍，涸泽生鱼，风雨大至，土崩溃，鳞见于陆，病腹满溏泄，肠呜，反下甚，而太溪绝者，死不治。上应岁星。","note":"岁土之气太过，雨湿之气就会流行，肾水就要受到侵淫，人们多患腹痛，手足逆冷，情志抑郁，身体不轻快，烦闷等病，上应天上的土星。如果土气过度旺盛，在人体就会肌肉萎缩，两足痿弱不能行走，经常抽搐拘挛，脚跟痛，水邪蓄积于中，而生胀满，吃东西减少，以至四肢不能举动，水气无权、土气独旺的现象。因此泉水涌出，河水溢满，甚至干涸的池塘也生长了鱼类，甚至会发生急风暴雨，使堤岸崩溃，河水泛滥，陆地出现鱼类，在人就会患肚腹胀满、大便溏泻、肠鸣、泄泻不止等症。如果太溪脉绝止的，大多死亡，无法治疗。上应天上的木星。 \n——《素问·气交变大论》"},{"title":"复","content":"木复，其脏脾肾，其虫倮毛，其物肌核，其病腹满四肢不举，大风迅至，邪伤脾也。","note":"其应于内脏为脾、肾，在虫类是倮虫毛虫，在物体属于人体肌肉和植物果核的一类，在病变为腹中胀满，四肢沉重，举动不便，由于土运太过，木气来复，所以大风迅速而来，其所见的疾病，多由邪气伤于脾脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"水郁，水郁之发，阳气乃避，阴气暴举，大寒乃至，川泽严凝，寒氛结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰脽痛，大关节不利，屈伸不便，善厥阴，痞坚，腹满。阳光不治，空积沈阴，白埃昏瞑，而乃发也。其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。","note":"水郁发作时，阳气退避，阴气暴起，大寒降临，川泽之水凝结为坚冰，寒雾结为霜雪，甚至黄黑昏暗的水气流行于气交之中，成为霜杀之气，水出现应时变化。所以人们多患伤寒病证，心痛，腰及臀部疼痛，大的关节不灵活，屈伸不利，经常出现四肢逆冷，腹部痞满坚硬，阳气不能发挥作用，空中积满阴霾之气，白色尘埃昏暗，这就是水郁将发的现象，发作时其气常出现在君、相二火前后。太空高深色黑，其气如散麻一样混乱无绪，隐约可见，色黑而微黄，这就是水郁将发的先兆。 \n——《素问·六元正纪大论》"}],"金运太过":[{"title":"三气之纪","content":"坚成之纪，是谓收引，天气洁，地气明，阳气随，阴治化，燥行其政，物以司成，收气繁布，化洽不终，其化成，其气削，其政肃，其令锐切，其动暴折疡疰，其德雾露萧飋，其变肃杀雕零，其谷稻黍，其畜鸡马，其果桃杏，其色白青丹，其味辛酸苦，其象秋，其经手太阴阳明，其脏肺肝，其虫介羽，其物壳络，其病喘喝胸凭仰息，上徵与正商同，其生齐，其病咳，政暴变则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。","note":"坚成的年份，称为收引。天高气爽洁净，地气亦清静明朗，阳气跟随隐气的权力而生化，因为阳明燥金之气当权，于是万物都成熟，但金运太过，故秋收之气旺盛四布，以致长夏的化气未尽而顺从收气行令。其化是提早收成，其气是削伐，其权力过于严厉肃杀，它权力的表现是尖锐锋利而刚颈，其在人体之变动为强烈的折伤和疮疡、皮肤病，其正常的性能是散布雾露凉风，其变化则为肃杀凋零的景象，在谷类是稻、黍，在畜类是鸡、马，在果类是桃、杏，在颜色是白、青、丹，它化生的在五味是辛、酸、苦，其象征为秋天，在人体上相应的经脉是手太阴、手阳明，在内脏是肺与肝，化生的在虫类是介虫羽虫，生成物体是属于皮壳和筋络的一类，如果发生病变，大都为气喘有声而呼吸困难。若遇金运太过而逢火气司天的年份，因为火能克金适得其平，所以说上徽与正商相同。金气得到抑制，则木气不受克制，生气就能正常行令，发生的病变为咳嗽。金运太过的年份剧变暴虐，各种树木受到影响，不能发荣，使得草类柔软脆弱都会焦头，但继之火气来复，好象夏天的气候前来相救，故炎热的天气又流行，蔓草被烧灼而渐至枯槁，人们发生病变，多由邪气伤于肺脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"金胜，岁金太过，燥气流行，肝木受邪。民病两胁下，少腹痛，目赤痛、眦疡、耳无所闻。肃杀而甚，则体重烦冤，胸痛引背，两胁满且痛引少腹，上应太白星。甚则喘咳逆气，肩背痛；尻阴股膝髀腨（骨行）足皆病，上应荧惑星。收气峻，生气下，草木敛，苍干雕陨，病反暴痛，胠胁不可反侧，咳逆甚而血溢，太冲绝者，死不治。上应太白星。","note":"岁金之气太过，燥气就会流行，肝木就要受到侵害，人们多患两肋下面少腹疼痛，目赤痛，眼角痒，耳聋等病。燥金之气过于亢盛，就会身体沉重、烦闷、胸痛牵引到背部、两胁胀满，而痛势下连少腹，由于金气太过，上应天上的金星，金气过度旺盛，在人体就会有喘息咳嗽、逆气，肩背疼痛，下连股、膝、髀、腨、、足等处疼痛的病症，由于火气来复，上应火星，若是金气过于严峻，木气被它克制，草木就要呈收敛之象，以至绿叶干枯凋落，在人们的疾病中，多见急剧疼痛，胠胁痛得不能转动，咳嗽气逆，甚则吐血衄血。肝脉绝止的，大多死亡，无法治愈。上应天上的太白星。 \n——《素问·气交变大论》"},{"title":"复","content":"火复，上徵与正商同，其生齐，其病咳，政暴变则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。","note":"上徽与正商相同。金气得到抑制，则木气不受克制，生气就能正常行令，发生的病变为咳嗽。金运太过的年份剧变暴虐，各种树木受到影响，不能发荣，使得草类柔软脆弱都会焦头，但继之火气来复，好象夏天的气候前来相救，故炎热的天气又流行，蔓草被烧灼而渐至枯槁，人们发生病变，多由邪气伤于肺脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"木郁，木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，膈咽不通，食饮不下，甚则耳呜眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色黄黑郁若，横云不起雨，而乃发也。其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。","note":"木郁发作时，太空中尘埃昏暗，云物扰动，大风暴起，掀开屋顶，树木折断，草木变异。所以人们易患胃脘当心疼痛，向上支撑两胁，咽喉阻塞不通，饮食物吞咽不下。甚至出现耳鸣，头目晕眩转动，认不清人，常常突然出现僵仆倒地，太空中尘埃弥漫，天山混为一色而分辨不清。或者秽浊之气混为一团，颜色黄黑，象云横垣太空而不下雨。将要发时，天上云气变换无常，广阔的原野上草倒卧不起，柔弱的树叶翻转而背部向上，高山谷底松鸣虎啸，这些均是将要发作的先兆。 \n——《素问·六元正纪大论》"}],"水运太过":[{"title":"三气之纪","content":"流衍之纪，是谓封藏，寒司物化，天地严凝，藏政以布，长令不扬，其化凛，其气坚，其政谧，其令流注，其动漂泄沃涌，其德凝惨寒雰，其变冰雪霜雹，其谷豆稷，其畜彘牛，其果栗枣，其色黑丹黅，其味咸苦甘，其象冬，其经足少阴太阳，其脏肾心，其虫鳞倮，其物濡满，其病胀，上羽而长气不化也。政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。","note":"流衍的年份，称为封藏。寒气执掌万物的变化，天地间严寒阴凝，闭藏之气行使其权力，火的生长之气不得发扬。其化为凛冽，其气则坚凝，其权力为安静，它权力的表现是流动灌注，其活动则或为漂浮，或为下泻，或为灌溉，或为外溢，其性能是阴凝惨淡、寒冷雾气，其气候的变化为冰雪霜雹，在谷类是豆、稷，在畜类是猪、牛，在果类是栗、枣，显露的颜色是黑、朱红与黄，化生的五味是咸、苦、甘，其象征为冬天，在人体相应的经脉是足少阴、足太阳，其应于内脏为肾和心，化生的虫类是鳞虫倮虫，生成物体属充满汁液肌肉的一类，如果发生病变是胀。若逢水气司天，水运更太过，二水相合，火气更衰，故流衍逢上羽，火生长之气更不能发挥作用。如果水行太过，则土气来复，而化气发动，以致地气上升，大雨不时下降，人们发生的病变，由于邪气伤于肾脏。 \n——《素问·五常政大论》"},{"title":"胜","content":"水胜，岁水太过，寒气流行，邪害心火。民病身热烦心，躁悸、阴厥、上下中寒、谵妄心痛、寒气早至，上应辰星。甚则腹大胫肿，喘咳寝汗出，憎风，大雨至，埃雾朦郁，上应镇星。上临太阳，雨冰雪霜不时降，湿气变物，病反腹满肠呜溏泄，食不化，渴而妄冒，神门绝者，死不治，上应荧惑辰星。","note":"岁水之气太过，就会寒气流行，心火从而受到侵害，人们多患身热、心烦、焦躁心跳，虚寒厥冷，全身发冷、谵语、心痛等病。在气候方面是寒气早至，上应水星水气过度旺盛，在人体就会有腹水、足胫浮肿、气喘咳嗽、盗汗、怕风等病症。由于水气盛，因而大雨下降，尘雾迷肿不清，土气来复，上应土星。如遇太阳寒水司天，则会冰雹霜雪不时下降，湿气太盛，致使物变其形。在人们的疾病中，多见肚腹胀满、肠鸣、溏泻、食物不化、渴而眩晕等症。心脉绝止的，大多数会死亡，无法治疗。上应水星却显得很亮。 \n——《素问·气交变大论》"},{"title":"复","content":"土复，政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。","note":"如果水行太过，则土气来复，而化气发动，以致地气上升，大雨不时下降，人们发生的病变，由于邪气伤于肾脏。 \n——《素问·五常政大论》"},{"title":"郁发","content":"火郁，火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背面首，四支䐜[chēn]愤，胪胀疡痱，呕逆瘈瘲，骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊?，善暴死。刻终大温，汗濡玄府，其乃发也。其气四。动复则静，阳极反阴，湿令乃化乃成，华发水凝，山川冰雪，焰阳午泽，怫之先兆也。","note":"火郁发作时，太空中昏朦不清，太阳光被遮盖而不明显，炎热流行，暴暑来临，山泽间如火燎烤，树木被蒸烤得流出汁液，大厦上升腾烟雾，地面上浮显出白色如霜的盐卤，聚积的水逐渐减少，蔓生的藤草枯萎焦黄，风热妄行。伤及心神，人们言语惑乱，湿的气化随后而生。所以人们患少气，疮疡痈肿，胁肋胸腹、背、头面、四肢胀满不适，生疮疡痱子，呕逆，筋脉抽搐，骨痛，关节抽动，泻下如注，温疟，腹中突然疼痛，血外流不止，精液减少，目赤，心热，甚至心中烦闷，昏晕等，容易引起突然死亡。一日百刻将尽时，气温升高，汗流满面。当发作时，多在四气之时。动到极点就转为静，阳极转阴，因而湿气乃化乃成。开花时节水反凝聚成冰，山川出现冰雪，中午时湖泽中出现烟雾，是火郁发作的先兆。 \n——《素问·六元正纪大论》"}],"木运不及":[{"title":"三气之纪","content":"委和之纪，是谓胜生，生气不政，化气乃扬，长气自平，收令乃早，凉雨时降，风云并兴，草木晚荣，苍干雕落，物秀而实，肤肉内充，其气敛，其用聚，其动緛戾拘缓，其发惊骇，其脏肝，其果枣李，其实核壳，其谷稷稻，其味酸辛，其色白苍，其畜犬鸡，其虫毛介，其主雾露凄沧，其声角商，其病摇动注恐，从金化也，少角与判商同，上角与正角同，上商与正商同，其病肢废痈肿疮疡，其甘虫，邪伤肝也，上宫与正宫同，萧飋肃杀则炎赫沸腾，眚于三，所谓复也，其主飞蠹蛆雉，乃为雷霆。","note":"委和的年份，称为胜生。生气不能很好的行使职权，化气于是发扬（土不畏木），长气自然平静（木不能生火），收令于是提早（金胜木），而凉雨不时下降，风云经常发起，草木不能及时繁荣，并且易于干枯凋落，万物早秀早熟，皮肉充实。其气收敛，其作用拘束，不得曲直伸展，在人体的变动是筋络拘挛无力，或者易于惊骇，其应于内脏为肝，在果类是枣、李，其所充实的是核和壳，在谷类是稷、稻，在五味是酸、辛，在颜色是白而苍，在畜类是犬和鸡，在虫类是毛虫和介虫，所主的气候是雾露寒冷之气，在声音是角、商，若发生病变则摇动和恐惧，这是由于木运不及而从金化的关系。所以少角等同判商。若逢厥阴风木司天，则不及的木运得司天之助，也可以成为平气，所以委和逢上角，则其气可与正角相同。若逢阳明燥金司天，则木运更衰，顺从金气用事，而成为金之平气，所以逢上商便和正商相同。在人体可发生四肢萎弱、痈肿、疮疡、生虫等病，这是由于雅气伤肝的关系。如正当太阴湿土司天，因土不畏，亦能形成土气用事，而成为土之平气，所以逢上宫则和正宫相同。故委年的年份，起初是一片肃杀的景象，但随之则为火热蒸腾，其灾害应于三（东方），这是由于金气克木，迫使火气前来报复。当火气来复，主多飞虫、蛆虫、蛆虫和雉木郁火复，发为雷霆。 \n——《素问·五常政大论》"},{"title":"胜","content":"金胜，岁木不及，燥乃大行，生气失应，草木晚荣，肃杀而甚，则刚木辟者，悉萎苍干，上应太白星。民病中清，胠胁痛，少腹痛，肠呜、溏泄。凉雨时至，上应太白星，其谷苍。上临阳明，生气失政，草木再荣，化气乃急，上应太白镇星，其主苍早。","note":"岁木之气不及，燥气然后流行，生气不能及时而来，草木就要晚荣。金气亢盛，劲硬的树木就会破折如劈，柔嫩的枝叶都会萎顿枯干，上应天上的金星。在人们则多患中气虚寒、胠胁部疼痛、少腹痛、肠鸣、溏泄。在气候方面，是凉雨时至。这一切均与天上的金星相应。在谷类，则不能成熟，呈现青苍色。如遇阳明司天，木气不能行其政令，土气兴起，草木再度繁茂，于是生化之气就显得峻急，而谷类也就不易结实了。因为燥、土二气俱盛，所以天的金星、土星俱明。 \n——《素问·气交变大论》"},{"title":"复","content":"火复，复则埃郁，大雨且至，黑气乃辱，病鹜溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身，上应镇星、辰星，玄谷不成。","note":"水气克火，则火的土气来复，于是土湿之气上蒸为云，大雨将至，水气下降，在人多见大便溏泻，腹满，饮食不下，肚中寒冷，肠鸣和泻下如注，腹痛，突然拘挛、痿、痹而足不能支持身体。上应土星水星，黑色之谷不能长熟。 \n——《素问·五常政大论》"},{"title":"郁发","content":"木郁，木郁之发，太虚埃昏，云物以扰，大风乃至，屋发折木，木有变。故民病胃脘当心而痛，上支两胁，膈咽不通，食饮不下，甚则耳呜眩转，目不识人，善暴僵仆。太虚苍埃，天山一色，或气浊色黄黑郁若，横云不起雨，而乃发也。其气无常。长川草偃，柔叶呈阴，松吟高山，虎啸岩岫，怫之先兆也。","note":"木郁发作时，太空中尘埃昏暗，云物扰动，大风暴起，掀开屋顶，树木折断，草木变异。所以人们易患胃脘当心疼痛，向上支撑两胁，咽喉阻塞不通，饮食物吞咽不下。甚至出现耳鸣，头目晕眩转动，认不清人，常常突然出现僵仆倒地，太空中尘埃弥漫，天山混为一色而分辨不清。或者秽浊之气混为一团，颜色黄黑，象云横垣太空而不下雨。将要发时，天上云气变换无常，广阔的原野上草倒卧不起，柔弱的树叶翻转而背部向上，高山谷底松鸣虎啸，这些均是将要发作的先兆。 \n——《素问·六元正纪大论》"}],"火运不及":[{"title":"三气之纪","content":"伏明之纪，是谓胜长，长气不宣，脏气反布，收气自政，化令乃衡，寒清数举，暑令乃薄，承化物生，生而不长，成实而稚，遇化已老，阳气屈伏，蛰虫早藏，其气郁，其用暴，其动彰伏变易，其发痛，其脏心，其果栗桃，其实络濡，其谷豆稻，其味苦咸，其色玄丹，其畜马彘，其虫羽鳞，其主冰雪霜寒，其声徵羽，其病昏惑悲忘，从水化也，少徵与少羽同，上商与正商同，邪伤心也，凝惨凛冽则暴雨霖霪，眚于九，其主骤注雷霆震惊，沉霒淫雨。","note":"伏明的年份，称为胜长。长气不得发扬，藏气反见布散，收气也擅自行使自行使职权，化气平定而不能发展，寒冷之气常现，暑热之气衰薄，万物虽承土的化气而生，但因火运不足，既生而不能成长，虽能结实，然而很小，及至生化的时候，已经衰老，阳气屈伏，蛰虫早藏。火气郁结，所以当其发作时，必然横暴，其变动每隐现多变，在人体病发为痛，其应于内脏为心，其在果类为栗和桃，其所充实的是络和汁，在谷类是豆和稻，在五味是苦和咸，在颜色是玄和丹，在畜类是马和猪，在虫类是羽虫鳞虫，在气候主冰雪霜寒，在声音是徽、羽，若发生病变则为精神昏乱，悲哀易忘，这是火运不及而从水化的关系。所以少徽和少羽相同。若逢阳明燥金司天，因金不畏火，形成金气用事，而成为金之平气，所以伏明逢上商则与正商相同。故所发之病，是由于邪气伤心，火运衰，所以有阴凝惨淡，寒风凛冽的现象，但随之而暴雨淋漓不止，其灾害于九（南方），这是土气来复，以致暴雨下注，雷霆震惊，乌云蔽日，阴雨连绵。 \n——《素问·五常政大论》"},{"title":"胜","content":"水胜，岁火不及，寒乃大行，长政不用，物荣而下。凝惨而甚，则阳气不化，乃折荣美，上应辰星。民病胸中痛、胁支满，两胁痛，膺背肩胛间及两臂内痛，郁冒蒙眛，心痛暴喑，胸复大，胁下与腰背相引而痛，甚则屈不能伸，髋髀如别，上应荧惑辰星，其谷丹。","note":"岁火之气不及，寒气就会大规模流行。夏天生长之气不能行其政令，植物就会由茂盛走向零落。寒凉之气过甚，阳气不能生化，因而万物的荣美也就被摧残了。相应天上的水星，在人们多患胸痛，胁部胀满，两胁疼痛，胸膺部、背部、肩胛之间以及两臂内侧都感疼痛，气都上冒，视物不清，心痛，突然失音，胸腹大，胁下与腰背互相牵引而痛，甚则病势发展到屈不能伸，髋骨与股部好像裂开一样。因为火受水气制约，所以上应天水星，五谷不成熟而其色红。 \n——《素问·气交变大论》"},{"title":"复","content":"土复，复则埃郁，大雨且至，黑气乃辱，病鹜溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身，上应镇星、辰星，玄谷不成。","note":"水气克火，则火的土气来复，于是土湿之气上蒸为云，大雨将至，水气下降，在人多见大便溏泻，腹满，饮食不下，肚中寒冷，肠鸣和泻下如注，腹痛，突然拘挛、痿、痹而足不能支持身体。上应土星水星，黑色之谷不能长熟。 \n——《素问·五常政大论》"},{"title":"郁发","content":"火郁，火郁之发，太虚肿翳，大明不彰，炎火行，大暑至，山泽燔燎，材木流津，广厦腾烟，土浮霜卤，止水乃减，蔓草焦黄，风行惑言，湿化乃后。故民病少气，疮疡痈肿，胁腹胸背面首，四支䐜[chēn]愤，胪胀疡痱，呕逆瘈瘲，骨痛，节乃有动，注下温疟，腹中暴痛，血溢流注，精液乃少，目赤心热，甚则瞀闷懊?，善暴死。刻终大温，汗濡玄府，其乃发也。其气四。动复则静，阳极反阴，湿令乃化乃成，华发水凝，山川冰雪，焰阳午泽，怫之先兆也。","note":"火郁发作时，太空中昏朦不清，太阳光被遮盖而不明显，炎热流行，暴暑来临，山泽间如火燎烤，树木被蒸烤得流出汁液，大厦上升腾烟雾，地面上浮显出白色如霜的盐卤，聚积的水逐渐减少，蔓生的藤草枯萎焦黄，风热妄行。伤及心神，人们言语惑乱，湿的气化随后而生。所以人们患少气，疮疡痈肿，胁肋胸腹、背、头面、四肢胀满不适，生疮疡痱子，呕逆，筋脉抽搐，骨痛，关节抽动，泻下如注，温疟，腹中突然疼痛，血外流不止，精液减少，目赤，心热，甚至心中烦闷，昏晕等，容易引起突然死亡。一日百刻将尽时，气温升高，汗流满面。当发作时，多在四气之时。动到极点就转为静，阳极转阴，因而湿气乃化乃成。开花时节水反凝聚成冰，山川出现冰雪，中午时湖泽中出现烟雾，是火郁发作的先兆。 \n——《素问·六元正纪大论》"}],"土运不及":[{"title":"三气之纪","content":"卑监之纪，是谓减化，化气不令，生政独彰，长气整，雨乃愆，收气平，风寒并兴，草木荣美，秀而不实，成而秕也，其气散，其用静定，其动疡涌分溃痈肿，其发濡滞，其脏脾，其果李栗，其实濡核，其谷豆麻，其味酸甘，其色苍黄，其畜牛犬，其虫倮毛，其主飘怒振发，其声宫角，其病留满痞塞，从木化也，少宫与少角同，上宫与正宫同，上角与正角同，其病飧泄，邪伤脾也，振拉飘扬则苍干散落，其眚四维，其主败折虎狼，清气乃用，生政乃辱。","note":"卑监的年份，称为减化。土的化气不得其令，而木的生气独旺，长气自能完整如常，雨水不能及时下降，收气平定，风寒并起，草木虽繁荣美丽，但秀而不能成实，所成的只是空壳或饱满的一类东西。其七散漫，其作用不足而过于静定，在人体的变动为病发疮疡，脓多、溃烂、痈肿，并发展为水气不行，其应于内脏为脾，在果类是李和栗，其所充实的是液汁和核，在谷类是豆和麻，在五味是酸、甘，在颜色是苍、黄，在畜类是牛和犬，在虫类是倮虫毛虫，因木胜风动，有振动摧折之势，在声音是宫、角，若发生病变则为胀满否塞不通，这是土运不及而从木化的关系。所以少宫和少角相同。若逢太阴湿土司天，虽土运不及，但得司天之助，也可成为平气，所以监逢上宫则和正宫相同。若逢厥阴风木司天，则土运更衰，顺从木气用事，而成为木知平气，所以逢上角则和正角相同。在发病来讲，消化不良的泄泻，是邪气伤脾的关系。土衰木胜，所以见风势振动，摧折飘扬的现象，随之而草木干枯凋落，其灾害应于中宫而通于四方。由于金气来复，所以有主败坏折伤，由于户；有如虎狼之势，清气发生作用，生气便被抑制而不能行使权力。 \n——《素问·五常政大论》"},{"title":"胜","content":"木胜，岁土不及，风乃大行，化气不令，草木茂荣。飘扬而甚，秀而不实，上应岁星。民病飧泄霍乱，体重腹痛，筋骨繇复，肌肉?酸，善怒，脏气举事，蛰虫早附，咸病寒中，上应岁星镇星，其谷黅。","note":"岁土之运不及，风气就大规模流行，而化气就不能行其政令。风木能生万物，所以草木茂盛，但因过分飘扬，虽然外秀却不能结实。上应木星，在人们多患飨泄、霍乱、身体重、腹痛、筋骨动摇强直、肌肉掣动发酸等症，并时常发怒。寒水之气乘机行动，虫类提前伏依在土里。人们一般都患中气虚寒。上应木星，土星，在谷类，其色黄而不能结实。 \n——《素问·气交变大论》"},{"title":"复","content":"金复，复则收政严峻，名木苍雕，胸胁暴痛，下引少腹，善大息，虫食甘黄，气客于脾， 谷乃减，民食少失味，苍谷乃损，上应太白、岁星。上临厥阴，流水不冰，蛰虫来见，脏气不用，白乃不复，上应岁星，民乃康。","note":"土受木气的克制，则其金气来复，于是秋气当令，呈现出肃杀严峻之气，因此大木凋谢，在人体就会有胸胁突然疼痛，牵引小腹，频频叹气等症。甘黄五谷都被虫食了。邪气客于脾土，黄色的谷类结实减少，人们吃得少，而且感到没有滋味。金气胜木，青色之谷受到损害，上应金星、木星。如遇厥阴司天，少阳在泉，则流水不能结冰，蛰伏的虫类又重新出现，寒水之气不能用事，金气也就不得再盛。上应木星，人们也就健康了。 \n——《素问·五常政大论》"},{"title":"郁发","content":"土郁，土郁之发，岩谷震惊，雷殷气交，埃昏黄黑，化为白气，飘骤高深，击石飞空，洪水乃从，川流漫衍，田牧土驹。化气乃敷，善为时雨，始生始长，始化始成。故民病心腹胀，胀呜而为数后，甚则心痛胁䐜[chēn] ，呕吐霍乱，饮发注下，胕肿身重。云奔雨府，霞拥朝阳，山泽埃昏，其乃发也。以其四气，云横天山，浮游生灭，怫之先兆。","note":"土郁发作时，山谷震动惊惧，隆隆雷声震动于气交之中，尘埃昏蒙，天地间昏黑。水湿化为白气，暴风骤雨降于高山深谷，击破山石，碎石飞于空中，洪水暴发漫溢川谷，大水退后，无数巨石耸立于田野，就象牧放的马匹。而后湿土之气敷布，时雨常降，于是自然万物开始生、长、化、成熟。所以人们易患腹胀满，肠鸣，大便次数增多，甚至心痛，胁肋撑胀，呕吐，霍乱，痰饮，水泻，浮肿，身重。云奔向南极，霞光壅遏早晨的太阳，山泽间尘埃昏蒙，这表明土郁将要暴发，发作的时间多在四时之气，浮云横于天山，或者飘浮，或者游动，或者产生，或者散失，这些都是郁结即将发作的先兆。 \n——《素问·六元正纪大论》"}],"金运不及":[{"title":"三气之纪","content":"从革之纪，是谓折收，收气乃后，生气乃扬，长化合德，火政乃宣，庶类以蕃，其气扬，其用躁切，其动铿禁瞀厥，其发咳喘，其脏肺，其果李杏，其实壳络，其谷麻麦，其味苦辛，其色白丹，其畜鸡羊，其虫介羽，其主明曜炎烁，其声商徵，其病嚏咳鼽衄，从火化也，少商与少徵同，上商与正商同，上角与正角同，邪伤肺也，炎光赫烈则冰雪霜雹，眚于七，其主鳞伏彘鼠，岁气早至，乃生大寒。","note":"从革的年份，称为折收，收气不能及时，生气得以发扬，长气和化气合而相得，火于是得以施行其权力，万物繁盛。其气发扬，其作用急噪，在人体的变动发病为咳嗽失音、烦闷气逆，发展为咳嗽气喘，其应于内脏为肺，在果类是李和杏，其所充实的是壳和络，在谷类是麻和麦，在五味是苦与辛，在颜色是白和朱红，在畜类是鸡和羊，在虫类是介虫羽虫。因为金虚火胜，主有发光灼热之势，在声音是商、徽，若发生病变则为喷嚏、咳嗽、鼻塞流滋、衄血，这是因金运不及而从火化的关系。所以少商和少徽相同。若逢阳明燥金司天，则金运虽不及，得司天之助，也能变为平气，所以从革逢上商就和正商相同。若逢厥阴风木司天，因金运不及，木不畏金，亦能形成木气用事而成为木知平气，所以逢上角便和正角相同。其病变是由于邪气伤于肺脏。因金衰火旺，所以火势炎热，但随之见冰雪霜雹，其灾害应于七（西方）。这是水气来复，故主如鳞虫伏藏，猪、鼠之阴沉，冬藏之气提早而至，于是发生大寒。 \n——《素问·五常政大论》"},{"title":"胜","content":"火胜，岁金不及，炎火乃行，生气乃用，长气专胜，庶物以茂，燥烁以行，上应荧惑星。民病肩背瞀重，鼽嚏、血便注下，收气乃后，上应太白星，其谷坚芒。","note":"岁金之气不及，火气就会流行，木气得行政令，生长之气专胜，万物因而繁茂。但火气旺盛了，气候就会干燥烁热。与此相应，天上火星光明。在人们多患肩背沉重，鼻流清涕，喷嚏，便血，泻下如注等病。金气被制，所以秋收之气后到。与此相应，天上金星失明，谷类不能成熟而呈现白色。 \n——《素问·气交变大论》"},{"title":"复","content":"水复，复则寒雨暴至，乃零冰雹霜雪杀物，阴厥且格，阳反上行，头脑户痛，延及囟顶发热，上应辰星，丹谷不成，民病口疮，甚则心痛。","note":"金气被制以后，它的水气来复，于是寒雨暴至，然后降落冰雹霜雪，杀害万物。在人就会为寒逆所扰，使阳气反而上行，以致头后部疼痛，连及脑顶，身体发热。上应水星，红色谷类不能成熟，人们多患口中生疮，甚至发生心痛等症。 \n——《素问·五常政大论》"},{"title":"郁发","content":"金郁，金郁之发，天洁地明，风清气切，大凉乃举，草树浮烟，燥气以行，霿雾数起，杀气来至，草木苍干，金乃有声。故民病咳逆，心胁满引少腹，善暴痛，不可反侧，嗌干面尘，色恶。山泽焦枯，土凝霜卤，怫乃发也，其气五。夜零白露，林莽声凄，怫之兆也。","note":"金郁发作时，天气清洁，地气明亮，风清凉爽，气急切，清凉产生，草木上烟雾缭绕，燥气流行，雾气弥漫，肃杀之气降临，草木焦枯，秋声时鸣，所以人们患咳嗽，气逆，心胁胀满牵引腹中，经常出现突然疼痛，身体不能左右转动，咽喉干燥，尘土蒙面，面色败坏，山泽枯涸，地面上凝结出现象霜一样的白色盐卤，表明金郁将要暴发，其发多在五气当令之时，假若夜间降下白露，森林间发出凄惨的声音，就是金郁将发的先兆。 \n——《素问·六元正纪大论》"}],"水运不及":[{"title":"三气之纪","content":"涸流之纪，是谓反阳，藏令不举，化气乃昌，长气宣布，蛰虫不藏，土润水泉减，草木条茂，荣秀满盛，其气滞，其用渗泄，其动坚止，其发燥槁，其脏肾，其果枣杏，其实濡肉，其谷黍稷，其味甘咸，其色黅玄，其畜彘牛，其虫鳞倮，其主埃郁昏翳，其声羽宫，其病痿厥坚下，从土化也，少羽与少宫同，上宫与正宫同，其病癃閟，邪伤肾也，埃昏骤雨则振拉摧拔，眚于一，其主毛显狐狢，变化不藏。故乘危而行，不速而至，暴虐无德，灾反及之，微者复微，甚者复甚，气之常也。","note":"涸流的年份，称为反阳。藏气衰弱，不能行使其封藏的权力，化气因而昌盛，长气反见宣行而布达于四方，蛰虫应藏而不藏，土润泽而泉水减少，草木条达茂盛，万物繁荣秀丽而丰满。其气不得流畅，故其作用为暗中渗透泄，其变动为症结不行，发病为干躁枯槁，其应于内脏为肾，在果类是枣、杏，其所充实的是汁液和肉，在谷类是黍和稷，在五味是甘、咸，在颜色是黄、黑，在畜类是猪、牛，在虫类是鳞虫倮虫，水运衰，土气用事，故主有尘土昏郁的现象，在声音是羽、宫，在人体的病变为痿厥和下部的症结，这是水运不及而从土化的关系。所以少羽和少宫相同。若逢土气司天，则水运更衰，顺从土气用事，所以涸流逢上宫与正宫相同。其病见大小便不畅或闭塞不通，是邪气伤于肾脏。因水运不及，故尘埃昏蔽，或骤然下雨，但岁之反见大风振动，摧折倒拔，其灾害应于一（北方），这是木气来复，所以又见毛虫，善于变动而不主闭藏。 \n——《素问·五常政大论》"},{"title":"胜","content":"土胜，岁水不及，湿乃大行，长气反用，其化乃速，暑雨数至，上应镇星。民病腹满，身重濡泄，寒疡流水，腰股痛发，腘腨股膝不便，烦冤、足痿清厥，脚下痛，甚则胕肿，藏气不政，肾气不衡，上应辰星，其谷秬。上临太阴，则大寒数举，蛰虫早藏，地积坚冰，阳光不治，民病寒疾于下，甚则腹满浮肿，上应镇星，其主黅谷。","note":"岁水之气不及，湿气就大规模流行。水气不能制火，火气反行其令，其生化很快，暑雨屡次下降。与此相应，天上土星光明。在人们多患腹部胀满，身体重，湿泄，阴性疮疡，脓液稀薄，腰股发痛，腘、股、腨、膝部都不便利，烦闷，两脚萎弱，四肢清冷，脚下疼痛，甚则浮肿，这是冬藏之气不能行其政令，肾气失掉平衡的缘故。上应水星，黑色的谷类不能成熟。如遇太阴司天，寒水在泉，大的寒气常常侵袭，虫类很早就伏藏，地面上凝积厚冰，在天上的阳光不能发挥温暖作用，人们多患下部寒疾，严重的就腹满浮肿。上应土星，谷类黄色之稻成熟。 \n——《素问·气交变大论》"},{"title":"复","content":"木复，复则大风暴发，草偃木零，生长不鲜，面色时变，筋骨并辟，肉（目閏）瘛，目视（目巟）（目巟），物疏璺，肌肉胗发，气并鬲中，痛于心腹，黄气乃损，其谷不登，上应岁星。","note":"因为土气被水气制约，则其木气来复，就出现大风暴发，草类偃伏，木类凋零，因为风吹干裂，失去了生长的鲜泽。人的面色就也改变，筋骨拘急疼痛，肌肉跳动抽搐，两眼看物不清，有的东西看去像稍有裂纹，肌肉发出风疹。假如风气侵入胸膈里，就会产生心腹疼痛。这是木气太盛，土气受害，黄色的谷类不能成熟，而上应于木星。 \n——《素问·五常政大论》"},{"title":"郁发","content":"水郁，水郁之发，阳气乃避，阴气暴举，大寒乃至，川泽严凝，寒氛结为霜雪，甚则黄黑昏翳，流行气交，乃为霜杀，水乃见祥。故民病寒客心痛，腰脽痛，大关节不利，屈伸不便，善厥阴，痞坚，腹满。阳光不治，空积沈阴，白埃昏瞑，而乃发也。其气二火前后。太虚深玄，气犹麻散，微见而隐，色黑微黄，怫之先兆也。","note":"水郁发作时，阳气退避，阴气暴起，大寒降临，川泽之水凝结为坚冰，寒雾结为霜雪，甚至黄黑昏暗的水气流行于气交之中，成为霜杀之气，水出现应时变化。所以人们多患伤寒病证，心痛，腰及臀部疼痛，大的关节不灵活，屈伸不利，经常出现四肢逆冷，腹部痞满坚硬，阳气不能发挥作用，空中积满阴霾之气，白色尘埃昏暗，这就是水郁将发的现象，发作时其气常出现在君、相二火前后。太空高深色黑，其气如散麻一样混乱无绪，隐约可见，色黑而微黄，这就是水郁将发的先兆。 \n——《素问·六元正纪大论》"}]};

export const zhuQiDetails: LiuQiDetailTable = {"descript":"主气，主司一年季节中的正常气候变化。将一年二十四节气分为六步，每步4个节气，计60日87刻半，每气各主一步，按五行相生次序依次为：初之气厥阴风木，二之气少阴君火，三之气少阳相火，四之气太阴湿土，五之气阳明燥金，终之气太阳寒水，年年无异，静而守位。 \n——《五运六气体质辨识及选方用药指（体质篇）》","厥阴风木":[{"title":"淫胜","content":"厥阴之胜，耳鸣头眩，愦愦欲吐，胃鬲如寒，大风数举，倮虫不滋，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上支两胁，肠鸣飧泄，少腹痛，注下赤白，甚则呕吐，鬲咽不通。","note":"如果厥阴风木之气成为胜利者，在这样病态的气候里人们多发的疾病是耳鸣头眩，心中烦乱想吐，胃膈如同生活在寒冷的环境中，总是感觉寒冷。如果大风频繁的发作，倮虫不能滋生。在这样病态的气候里人们多发的疾病是胠胁气并，化而为热，小便黄赤，胃脘当心而疼，上肢两胁胀满，肠鸣飧泄，少腹疼痛，泄泻赤白，病严重时就要呕吐，膈咽之间阻塞不通。"},{"title":"淫胜治则","content":"厥阴之胜，治以甘清，佐以苦辛，以酸泻之。","note":"如果厥阴风木之气过于强盛，成为胜利者而致病，治疗这类疾病应该以甘清药物为主，以苦辛药物为辅，以酸味药物泻之。"},{"title":"复气","content":"厥阴之复，少腹坚满，里急暴痛。偃木飞沙，倮虫不荣。厥心痛，汗发呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。冲阳绝，死不治。","note":"厥阴风木之气变成复气的时候，形成的疾病表现为少腹坚满，里急暴痛的症状。如果复气严重则发生树木偃伏，沙土飞扬，倮虫不能发育等现象。复气严重时形成疾病表现为气厥心痛，出汗、呕吐，饮食不入，食入而又吐出，筋骨震颤，目眩，手足逆冷。严重的就会风邪入脾，成为食后吐出的食痹之症。往严重发展，等到冲阳脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"厥阴之复，治以酸寒，佐以甘辛，以酸泻之，以甘缓之。","note":"当厥阴风木之气变成复气形成疾病，治疗这类疾病应该以酸寒药物为主，以甘辛药物为辅，以酸味药物泻之，以甘味药物缓之。——《素问·至真要大论》"}],"少阳相火":[{"title":"淫胜","content":"少阳之胜，热客于胃，烦心心痛，目赤欲呕，呕酸善饥，耳痛溺赤，善惊谵妄，暴热消烁，草萎水涸，介虫乃屈，少腹痛，下沃赤白。","note":"少阳火气偏胜，热气客于胃，烦心，心痛，目赤，欲呕，呕酸，易饥饿，耳痛，小便赤色，易惊，谵妄；暴热之气消烁津液，草萎枯，水干涸，介虫屈伏，人们少腹疼痛，下痢赤白。"},{"title":"淫胜治则","content":"少阳之胜，治以辛寒，佐以苦咸，以甘泻之。","note":"如果少阳之气过于强盛，成为胜利者而致病，治疗这类疾病应该以辛寒药物为主，以苦咸药物为辅，以甘味药物泻之。"},{"title":"复气","content":"少阳之复，大热将至，枯燥燔爇，介虫乃耗，惊瘛咳衄，心热烦躁，便数憎风，厥气上行，面如浮埃，目乃瘛，火气内发，上为口糜，呕逆，血溢血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴引水浆，色变黄赤，少气脉萎，化而为水，传为胕肿，甚则入肺，咳而血泄。尺泽绝，死不治。","note":"少阳相火之气变成复气的时候，大热的气候将会到来，草木被炎热的气候炙烤的干枯干燥，介虫因为不喜欢炎热的气候，因而介虫会被炎热的气候伤耗气血。形成的疾病表现为惊瘈咳衄，心热烦燥，小便频数，怕风。厥逆之气上行，面色就会像蒙上浮尘，眼睛也潏动引掣。火气在体内发作，就会上为口干，呕逆，或为血溢，下行则为便血。发为疟疾，就有恶寒鼓栗的现象。寒极反热，咽部干燥，渴欲饮水，脸色变为黄赤，少阳脉气萎弱。热寒之气在体内交争，转变成为浮肿，严重则邪气入肺，咳而有血。往严重发展，等到尺泽脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阳之复，治以咸冷，佐以苦辛，以咸软之，以酸收之，辛苦发之；发不远热，无犯温凉。少阴同法。","note":"当少阳相火之气变成复气形成疾病，治疗这类疾病应该以咸冷药物为主，以苦辛药物为辅，以咸味药物软之，以酸味药物收之，以辛苦味药物发之，发不要太过，不要远离了热气正常运行的规则，使其恢复正常即可停止，也不要犯了温凉二气的运行规则，不要用药太过或不及，以调节到气血正常运行为原则，少阴之复气所致的病，用发汗之药与此同法。 \n——《素问·至真要大论》"}],"少阴君火":[{"title":"淫胜","content":"少阴之胜，心下热，善饥，齐下反动，气游三焦，炎暑至，木乃津，草乃萎，呕逆躁烦，腹满痛，溏泄，传为赤沃。","note":"如果少阴君火之气成为胜利者，在这样病态的气候里人们多发的疾病是心下热，爱饥饿，齐下反动，气游三焦。等到炎暑季节到来，树木就会被炎热的空气炙烤的流津液，草类乃因此枯萎。在这样病态的气候里人们多发的疾病是呕逆烦躁，腹部胀满而痛，大便溏泻，转变成为尿血。"},{"title":"淫胜治则","content":"少阴之胜，治以辛寒，佐以苦咸，以甘泻之。","note":"如果少阴君火之气过于强盛，成为胜利者而致病，治疗这类疾病应该以辛寒药物为主，以苦咸药物为辅，以甘味药物泻之。"},{"title":"复气","content":"少阴之复，懊热内作，烦燥鼽嚏，少腹绞痛，火见燔?，嗌燥分注时止，气动于左，上行于右，咳、皮肤痛、暴喑、心痛、郁冒不知人，乃洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气骨痿，隔肠不便，外为浮肿，哕噫。赤气后化，流水不冰，热气大行，介虫不复。病痱胗疮疡、痈疽痤痔，甚则入，肺，咳而鼻渊。天府绝，死不治。","note":"少阴君火之气变成复气的时候，形成的疾病表现为烦热从内部发作，烦躁，鼻流血，喷嚏，少腹绞痛，火现于外，身热如焚烧，咽嗌干燥，大小便时下时止，气动于左边而向上逆行于右侧，咳嗽，皮肤痛，突然失音，心痛，神志昏昏不省人事，继则洒浙恶寒，打寒战，妄言乱语，寒过去，又发烧，口渴而想喝水，少气，骨萎弱，肠道梗塞而大便不通，外现浮肿，呃逆嗳气。少阴君火之热气延后生化，致使流水在应该结冰的时令不能结冰，因此少阴君火热气大行，介虫因为喜欢清凉干燥的气候，属于自己的时令被火热的气候所占领，介虫因为不适应这种火热的气候，所以因为气候失常，介虫因此也不能恢复繁育昌盛。这时人们多患痱、胗、疮疡、痈疽、痤痔等外证，热邪过甚，就会入肺，发为咳嗽鼻渊。往严重发展，等到天府脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阴之复，治以咸寒，佐以苦辛，以甘泻之，以酸收之，辛苦发之，以咸软之。","note":"当少阴君火之气变成复气形成疾病，治疗这类疾病应该以咸寒药物为主，以苦辛药物为辅，以甘味药物泻之，以酸味药物收之，以辛苦药物发之，以咸味药物软之。 \n——《素问·至真要大论》"}],"太阴湿土":[{"title":"淫胜","content":"太阴之胜，火气内郁，疮疡于中，流散于外，病在胠胁，甚则心痛，热格，头痛喉痹项强，独胜则湿气内郁，寒迫下焦，痛留顶，互引眉间，胃满，雨数至，燥化乃见，少腹满，腰（月隹）重强，内不便，善注泄，足下温，头重，足胫胕肿，饮发于中，胕肿于上。","note":"如果太阴湿土之气成为胜利者，在这样病态的气候里人们多发的疾病是火气在人体内部郁结，就会酝酿成为疮疡，流散在外，则病在胠胁，严重时则会心疼，如果热气被阻隔在上部，就会发生头痛、喉痹、颈部强硬不灵活。如果没有热症，而是湿气独胜，郁结于里，湿寒之气迫于下焦，就会囟顶痛，牵扯眉间也痛，胃中满闷。如果是湿雨频繁，空气和人体之内湿气过重，只有用燥气来化解，才能够干燥正常，在这样病态的气候里人们多发的疾病是少腹满胀，腰椎沉重强直，湿气在体内过盛，而伸展不利，爱注泄，足下温暖，头部沉重，足胫肿，水饮发于内而上部出现浮肿。"},{"title":"淫胜治则","content":"太阴之胜，治以咸热，佐以辛甘，以苦泻之。","note":"如果太阴湿土之气过于强盛，成为胜利者而致病，治疗这类疾病应该以咸热药物为主，以辛甘药物为辅，以苦味药物泻之。"},{"title":"复气","content":"太阴之复，湿度乃举，体重中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声。大雨时行，鳞见于陆，头顶痛重，而掉瘈尤甚，呕而密默，唾吐清液，甚则入肾窍，泻无度。太溪绝，死不治。","note":"太阴湿土之气变成复气的时候，形成的疾病表现为湿气的病变就发生，身体沉重，胸满，饮食不消化，阴气上逆，胸中不爽快，水饮发于内，咳喘会夹杂着杂音。如果大雨时常下降，鳞虫类在平原陆地上出现。复气严重形成疾病表现为头顶痛重，在受到惊恐或震动的时候，更加厉害，呕吐，不愿动作，啐吐清水，往严重发展则湿邪入肾，泄泻没有节制。往严重发展，等到太溪脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阴之复，治以苦热，佐以酸辛，以苦泻之，燥之、泄之。","note":"当太阴湿土之气变成复气形成疾病，治疗这类疾病应该以苦热药物为主，以酸辛药物为辅，以苦味药物泻之，以燥味药物泄之。 \n——《素问·至真要大论》"}],"阳明燥金":[{"title":"淫胜","content":"阳明之胜，清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，大凉肃杀，华英改容，毛虫乃殃，胸中不便，嗌塞而咳。","note":"如果阳明燥金之气成为胜利者，在这样病态的气候里人们多发的疾病是清凉的病症在人体内部发作，左胠胁痛、溏泄、内则咽嗌窒塞，外则阴囊肿大。大凉肃杀之气横行，草木变为枯黄，这种寒凉的气候会使毛虫类遭殃。在这样病态的气候里人们多发的疾病是胸中不舒，咽嗌窒塞而且咳嗽。"},{"title":"淫胜治则","content":"阳明之胜，治以酸温，佐以辛甘，以苦泄之。","note":"如果阳明燥金之气过于强盛成为胜利者而致病，治疗这类疾病应该以酸温药物为主，以辛甘药物为辅，以苦味药物泄之。"},{"title":"复气","content":"阳明之复，清气大举，森木苍干，毛虫乃厉。病生胠胁，气归于左，善太息，甚则心痛，否满腹胀而泄，呕苦咳哕烦心，病在膈中，头痛，甚则入肝，惊骇筋挛。太冲绝，死不治。","note":"阳明燥金之气变成复气的时候，清凉之气就会大行，森林的树木开始变得苍老干枯，毛虫受到的伤害乃会非常厉害，因为毛虫喜欢春天温暖的环境，不能适应像秋天一样寒凉的气候。少阳相火变成复气形成疾病表现为疾病生于胠胁，其气偏于左侧不舒，爱叹息，严重则产生心痛，痞满，腹胀，泄泻，呕吐，咳嗽，呃逆，烦心。病在膈中，头痛，严重则邪气入肝，而发生惊惧、痉挛等症。往严重发展，等到太冲脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"阳明之复，治以辛温，佐以苦甘，以苦泄之，以苦下之，以酸补之。","note":"当阳明燥金之气变成复气形成疾病，治疗这类疾病应该以辛温药物为主，以苦甘药物为辅，以苦味药物泻之，以苦味药物下之，以酸味药物补之。 \n——《素问·至真要大论》"}],"太阳寒水":[{"title":"淫胜","content":"太阳之胜，凝凓且至，非时水冰，羽乃后化，痔疟发，寒厥入胃，则内生心痛，阴中乃疡，隐曲不利，互引阴股，筋肉拘苛，血脉凝泣，络满色变，或为血泄，皮肤否肿，腹满食减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，传为濡泻。","note":"如果太阳寒水之气成为胜利者，凝栗的寒气就会来到，不应该结冰的季节而水却结了冰，羽类之虫延迟生化。在这样病态的气候里人们多发的疾病是痔疮、疟疾。寒冷的厥逆之气入胃，气逆上冲，就会发生心痛，阴部生疮疡，小便不利，疼痛牵引两股内侧，筋肉拘急引缩，血脉凝滞，所以络脉满而色变，或为便血，皮肤因水气郁积而肿，腹中痞满，饮食减少，热气上行，因之头项巅顶脑户等处都感到疼痛，目如脱，寒气入于下焦，转变成为水泻。"},{"title":"淫胜治则","content":"客气或主气为：太阳寒水，太阳之胜，治以甘热，佐以辛酸，以咸泻之。","note":"如果太阳寒水之气过于强盛，成为胜利者而致病，治疗这类疾病应该以甘热药物为主，以辛酸药物为辅，以咸味药物泻之。"},{"title":"复气","content":"太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆食减，腰脽反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睪，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。","note":"太阳寒水之气变成复气的时候，则寒厥之气上行，水气凝结为寒雨和冰，羽虫（带有翅膀的虫类）乃会死亡，因为羽虫喜欢比较炎热的气候，所以遇上寒冷的气候不能适应就会发生死亡。少阳相火变成复气形成疾病表现为心胃生寒气，胸中不舒适，心痛，痞满，头痛，多伤惧，经常眩晕仆倒，纳食减少，腰椎疼痛，屈伸极不方便。如果复气严重，则会地裂冰坚，阳光不显温暖，复气变严重形成疾病表现为少腹痛，牵引睾丸，连腰脊都痛，逆气上冲于心，唾出清水，呃逆嗳气，甚则邪气入心，发生善忘善悲的现象。往严重发展，等到神门脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阳之复，治以咸热，佐以甘辛，以苦坚之。","note":"当太阳寒水之气变成复气形成疾病，治疗这类疾病应该以咸热药物为主，以甘辛药物为辅，以苦味药物坚之。 \n——《素问·至真要大论》"}]};

export const keQiDetails: LiuQiDetailTable = {"descript":"客气，因其运动不息，与固定的主气不同，如客之往来，故称客气。客气的运行亦分六步，其主司时段及交司时刻与主气相同，但两者运行次序则完全不同，每年各步的客气性质及其盛衰变化均有所不同。 \n——《五运六气三十二讲》","厥阴风木":[{"title":"淫胜","content":"厥阴之胜，耳鸣头眩，愦愦欲吐，胃鬲如寒，大风数举，倮虫不滋，胠胁气并，化而为热，小便黄赤，胃脘当心而痛，上支两胁，肠鸣飧泄，少腹痛，注下赤白，甚则呕吐，鬲咽不通。","note":"如果厥阴风木之气成为胜利者，在这样病态的气候里人们多发的疾病是耳鸣头眩，心中烦乱想吐，胃膈如同生活在寒冷的环境中，总是感觉寒冷。如果大风频繁的发作，倮虫不能滋生。在这样病态的气候里人们多发的疾病是胠胁气并，化而为热，小便黄赤，胃脘当心而疼，上肢两胁胀满，肠鸣飧泄，少腹疼痛，泄泻赤白，病严重时就要呕吐，膈咽之间阻塞不通。"},{"title":"淫胜治则","content":"厥阴之胜，治以甘清，佐以苦辛，以酸泻之。","note":"如果厥阴风木之气过于强盛，成为胜利者而致病，治疗这类疾病应该以甘清药物为主，以苦辛药物为辅，以酸味药物泻之。"},{"title":"复气","content":"厥阴之复，少腹坚满，里急暴痛。偃木飞沙，倮虫不荣。厥心痛，汗发呕吐，饮食不入，入而复出，筋骨掉眩清厥，甚则入脾，食痹而吐。冲阳绝，死不治。","note":"厥阴风木之气变成复气的时候，形成的疾病表现为少腹坚满，里急暴痛的症状。如果复气严重则发生树木偃伏，沙土飞扬，倮虫不能发育等现象。复气严重时形成疾病表现为气厥心痛，出汗、呕吐，饮食不入，食入而又吐出，筋骨震颤，目眩，手足逆冷。严重的就会风邪入脾，成为食后吐出的食痹之症。往严重发展，等到冲阳脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"厥阴之复，治以酸寒，佐以甘辛，以酸泻之，以甘缓之。","note":"当厥阴风木之气变成复气形成疾病，治疗这类疾病应该以酸寒药物为主，以甘辛药物为辅，以酸味药物泻之，以甘味药物缓之。——《素问·至真要大论》"}],"少阳相火":[{"title":"淫胜","content":"少阳之胜，热客于胃，烦心心痛，目赤欲呕，呕酸善饥，耳痛溺赤，善惊谵妄，暴热消烁，草萎水涸，介虫乃屈，少腹痛，下沃赤白。","note":"少阳火气偏胜，热气客于胃，烦心，心痛，目赤，欲呕，呕酸，易饥饿，耳痛，小便赤色，易惊，谵妄；暴热之气消烁津液，草萎枯，水干涸，介虫屈伏，人们少腹疼痛，下痢赤白。"},{"title":"淫胜治则","content":"少阳之胜，治以辛寒，佐以苦咸，以甘泻之。","note":"如果少阳之气过于强盛，成为胜利者而致病，治疗这类疾病应该以辛寒药物为主，以苦咸药物为辅，以甘味药物泻之。"},{"title":"复气","content":"少阳之复，大热将至，枯燥燔爇，介虫乃耗，惊瘛咳衄，心热烦躁，便数憎风，厥气上行，面如浮埃，目乃瘛，火气内发，上为口糜，呕逆，血溢血泄，发而为疟，恶寒鼓栗，寒极反热，嗌络焦槁，渴引水浆，色变黄赤，少气脉萎，化而为水，传为胕肿，甚则入肺，咳而血泄。尺泽绝，死不治。","note":"少阳相火之气变成复气的时候，大热的气候将会到来，草木被炎热的气候炙烤的干枯干燥，介虫因为不喜欢炎热的气候，因而介虫会被炎热的气候伤耗气血。形成的疾病表现为惊瘈咳衄，心热烦燥，小便频数，怕风。厥逆之气上行，面色就会像蒙上浮尘，眼睛也潏动引掣。火气在体内发作，就会上为口干，呕逆，或为血溢，下行则为便血。发为疟疾，就有恶寒鼓栗的现象。寒极反热，咽部干燥，渴欲饮水，脸色变为黄赤，少阳脉气萎弱。热寒之气在体内交争，转变成为浮肿，严重则邪气入肺，咳而有血。往严重发展，等到尺泽脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阳之复，治以咸冷，佐以苦辛，以咸软之，以酸收之，辛苦发之；发不远热，无犯温凉。少阴同法。","note":"当少阳相火之气变成复气形成疾病，治疗这类疾病应该以咸冷药物为主，以苦辛药物为辅，以咸味药物软之，以酸味药物收之，以辛苦味药物发之，发不要太过，不要远离了热气正常运行的规则，使其恢复正常即可停止，也不要犯了温凉二气的运行规则，不要用药太过或不及，以调节到气血正常运行为原则，少阴之复气所致的病，用发汗之药与此同法。 ——《素问·至真要大论》"}],"少阴君火":[{"title":"淫胜","content":"少阴之胜，心下热，善饥，齐下反动，气游三焦，炎暑至，木乃津，草乃萎，呕逆躁烦，腹满痛，溏泄，传为赤沃。","note":"如果少阴君火之气成为胜利者，在这样病态的气候里人们多发的疾病是心下热，爱饥饿，齐下反动，气游三焦。等到炎暑季节到来，树木就会被炎热的空气炙烤的流津液，草类乃因此枯萎。在这样病态的气候里人们多发的疾病是呕逆烦躁，腹部胀满而痛，大便溏泻，转变成为尿血。"},{"title":"淫胜治则","content":"少阴之胜，治以辛寒，佐以苦咸，以甘泻之。","note":"如果少阴君火之气过于强盛，成为胜利者而致病，治疗这类疾病应该以辛寒药物为主，以苦咸药物为辅，以甘味药物泻之。"},{"title":"复气","content":"少阴之复，懊热内作，烦燥鼽嚏，少腹绞痛，火见燔?，嗌燥分注时止，气动于左，上行于右，咳、皮肤痛、暴喑、心痛、郁冒不知人，乃洒淅恶寒振栗，谵妄，寒已而热，渴而欲饮，少气骨痿，隔肠不便，外为浮肿，哕噫。赤气后化，流水不冰，热气大行，介虫不复。病痱胗疮疡、痈疽痤痔，甚则入，肺，咳而鼻渊。天府绝，死不治。","note":"少阴君火之气变成复气的时候，形成的疾病表现为烦热从内部发作，烦躁，鼻流血，喷嚏，少腹绞痛，火现于外，身热如焚烧，咽嗌干燥，大小便时下时止，气动于左边而向上逆行于右侧，咳嗽，皮肤痛，突然失音，心痛，神志昏昏不省人事，继则洒浙恶寒，打寒战，妄言乱语，寒过去，又发烧，口渴而想喝水，少气，骨萎弱，肠道梗塞而大便不通，外现浮肿，呃逆嗳气。少阴君火之热气延后生化，致使流水在应该结冰的时令不能结冰，因此少阴君火热气大行，介虫因为喜欢清凉干燥的气候，属于自己的时令被火热的气候所占领，介虫因为不适应这种火热的气候，所以因为气候失常，介虫因此也不能恢复繁育昌盛。这时人们多患痱、胗、疮疡、痈疽、痤痔等外证，热邪过甚，就会入肺，发为咳嗽鼻渊。往严重发展，等到天府脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"少阴之复，治以咸寒，佐以苦辛，以甘泻之，以酸收之，辛苦发之，以咸软之。","note":"当少阴君火之气变成复气形成疾病，治疗这类疾病应该以咸寒药物为主，以苦辛药物为辅，以甘味药物泻之，以酸味药物收之，以辛苦药物发之，以咸味药物软之。 ——《素问·至真要大论》"}],"太阴湿土":[{"title":"淫胜","content":"太阴之胜，火气内郁，疮疡于中，流散于外，病在胠胁，甚则心痛，热格，头痛喉痹项强，独胜则湿气内郁，寒迫下焦，痛留顶，互引眉间，胃满，雨数至，燥化乃见，少腹满，腰（月隹）重强，内不便，善注泄，足下温，头重，足胫胕肿，饮发于中，胕肿于上。","note":"如果太阴湿土之气成为胜利者，在这样病态的气候里人们多发的疾病是火气在人体内部郁结，就会酝酿成为疮疡，流散在外，则病在胠胁，严重时则会心疼，如果热气被阻隔在上部，就会发生头痛、喉痹、颈部强硬不灵活。如果没有热症，而是湿气独胜，郁结于里，湿寒之气迫于下焦，就会囟顶痛，牵扯眉间也痛，胃中满闷。如果是湿雨频繁，空气和人体之内湿气过重，只有用燥气来化解，才能够干燥正常，在这样病态的气候里人们多发的疾病是少腹满胀，腰椎沉重强直，湿气在体内过盛，而伸展不利，爱注泄，足下温暖，头部沉重，足胫肿，水饮发于内而上部出现浮肿。"},{"title":"淫胜治则","content":"太阴之胜，治以咸热，佐以辛甘，以苦泻之。","note":"如果太阴湿土之气过于强盛，成为胜利者而致病，治疗这类疾病应该以咸热药物为主，以辛甘药物为辅，以苦味药物泻之。"},{"title":"复气","content":"太阴之复，湿度乃举，体重中满，食饮不化，阴气上厥，胸中不便，饮发于中，咳喘有声。大雨时行，鳞见于陆，头顶痛重，而掉瘈尤甚，呕而密默，唾吐清液，甚则入肾窍，泻无度。太溪绝，死不治。","note":"太阴湿土之气变成复气的时候，形成的疾病表现为湿气的病变就发生，身体沉重，胸满，饮食不消化，阴气上逆，胸中不爽快，水饮发于内，咳喘会夹杂着杂音。如果大雨时常下降，鳞虫类在平原陆地上出现。复气严重形成疾病表现为头顶痛重，在受到惊恐或震动的时候，更加厉害，呕吐，不愿动作，啐吐清水，往严重发展则湿邪入肾，泄泻没有节制。往严重发展，等到太溪脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阴之复，治以苦热，佐以酸辛，以苦泻之，燥之、泄之。","note":"当太阴湿土之气变成复气形成疾病，治疗这类疾病应该以苦热药物为主，以酸辛药物为辅，以苦味药物泻之，以燥味药物泄之。 ——《素问·至真要大论》"}],"阳明燥金":[{"title":"淫胜","content":"阳明之胜，清发于中，左胠胁痛，溏泄，内为嗌塞，外发颓疝，大凉肃杀，华英改容，毛虫乃殃，胸中不便，嗌塞而咳。","note":"如果阳明燥金之气成为胜利者，在这样病态的气候里人们多发的疾病是清凉的病症在人体内部发作，左胠胁痛、溏泄、内则咽嗌窒塞，外则阴囊肿大。大凉肃杀之气横行，草木变为枯黄，这种寒凉的气候会使毛虫类遭殃。在这样病态的气候里人们多发的疾病是胸中不舒，咽嗌窒塞而且咳嗽。"},{"title":"淫胜治则","content":"阳明之胜，治以酸温，佐以辛甘，以苦泄之。","note":"如果阳明燥金之气过于强盛成为胜利者而致病，治疗这类疾病应该以酸温药物为主，以辛甘药物为辅，以苦味药物泄之。"},{"title":"复气","content":"阳明之复，清气大举，森木苍干，毛虫乃厉。病生胠胁，气归于左，善太息，甚则心痛，否满腹胀而泄，呕苦咳哕烦心，病在膈中，头痛，甚则入肝，惊骇筋挛。太冲绝，死不治。","note":"阳明燥金之气变成复气的时候，清凉之气就会大行，森林的树木开始变得苍老干枯，毛虫受到的伤害乃会非常厉害，因为毛虫喜欢春天温暖的环境，不能适应像秋天一样寒凉的气候。少阳相火变成复气形成疾病表现为疾病生于胠胁，其气偏于左侧不舒，爱叹息，严重则产生心痛，痞满，腹胀，泄泻，呕吐，咳嗽，呃逆，烦心。病在膈中，头痛，严重则邪气入肝，而发生惊惧、痉挛等症。往严重发展，等到太冲脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"阳明之复，治以辛温，佐以苦甘，以苦泄之，以苦下之，以酸补之。","note":"当阳明燥金之气变成复气形成疾病，治疗这类疾病应该以辛温药物为主，以苦甘药物为辅，以苦味药物泻之，以苦味药物下之，以酸味药物补之。 ——《素问·至真要大论》"}],"太阳寒水":[{"title":"淫胜","content":"太阳之胜，凝凓且至，非时水冰，羽乃后化，痔疟发，寒厥入胃，则内生心痛，阴中乃疡，隐曲不利，互引阴股，筋肉拘苛，血脉凝泣，络满色变，或为血泄，皮肤否肿，腹满食减，热反上行，头项囟顶脑户中痛，目如脱，寒入下焦，传为濡泻。","note":"如果太阳寒水之气成为胜利者，凝栗的寒气就会来到，不应该结冰的季节而水却结了冰，羽类之虫延迟生化。在这样病态的气候里人们多发的疾病是痔疮、疟疾。寒冷的厥逆之气入胃，气逆上冲，就会发生心痛，阴部生疮疡，小便不利，疼痛牵引两股内侧，筋肉拘急引缩，血脉凝滞，所以络脉满而色变，或为便血，皮肤因水气郁积而肿，腹中痞满，饮食减少，热气上行，因之头项巅顶脑户等处都感到疼痛，目如脱，寒气入于下焦，转变成为水泻。"},{"title":"淫胜治则","content":"客气或主气为：太阳寒水，太阳之胜，治以甘热，佐以辛酸，以咸泻之。","note":"如果太阳寒水之气过于强盛，成为胜利者而致病，治疗这类疾病应该以甘热药物为主，以辛酸药物为辅，以咸味药物泻之。"},{"title":"复气","content":"太阳之复，厥气上行，水凝雨冰，羽虫乃死。心胃生寒，胸膈不利，心痛否满，头痛善悲，时眩仆食减，腰脽反痛，屈伸不便，地裂冰坚，阳光不治，少腹控睪，引腰脊，上冲心，唾出清水，及为哕噫，甚则入心，善忘善悲。神门绝，死不治。","note":"太阳寒水之气变成复气的时候，则寒厥之气上行，水气凝结为寒雨和冰，羽虫（带有翅膀的虫类）乃会死亡，因为羽虫喜欢比较炎热的气候，所以遇上寒冷的气候不能适应就会发生死亡。少阳相火变成复气形成疾病表现为心胃生寒气，胸中不舒适，心痛，痞满，头痛，多伤惧，经常眩晕仆倒，纳食减少，腰椎疼痛，屈伸极不方便。如果复气严重，则会地裂冰坚，阳光不显温暖，复气变严重形成疾病表现为少腹痛，牵引睾丸，连腰脊都痛，逆气上冲于心，唾出清水，呃逆嗳气，甚则邪气入心，发生善忘善悲的现象。往严重发展，等到神门脉气绝了的时候，就已经发展成为不能治愈的死症了。"},{"title":"复气治则","content":"太阳之复，治以咸热，佐以甘辛，以苦坚之。","note":"当太阳寒水之气变成复气形成疾病，治疗这类疾病应该以咸热药物为主，以甘辛药物为辅，以苦味药物坚之。 ——《素问·至真要大论》"}]};
